cat > /workspace/src/skeema/log.go << 'GOEOF'
package main

import (
	"fmt"
	"os"
	"time"
)

// Log level constants
const (
	LevelDebug = "DEBUG"
	LevelInfo  = "INFO"
	LevelWarn  = "WARN"
	LevelError = "ERROR"
)

var debugMode bool

func logTimestamp() string {
	return time.Now().Format("2006-01-02 15:04:05")
}

func logLine(level, message string) string {
	var padding string
	switch level {
	case LevelInfo, LevelWarn:
		padding = "  "
	default:
		padding = " "
	}
	return fmt.Sprintf("%s [%s]%s%s", logTimestamp(), level, padding, message)
}

func logDebug(format string, args ...interface{}) {
	if debugMode {
		msg := fmt.Sprintf(format, args...)
		fmt.Fprintln(os.Stderr, logLine(LevelDebug, msg))
	}
}

func logInfo(format string, args ...interface{}) {
	msg := fmt.Sprintf(format, args...)
	fmt.Fprintln(os.Stderr, logLine(LevelInfo, msg))
}

func logWarn(format string, args ...interface{}) {
	msg := fmt.Sprintf(format, args...)
	fmt.Fprintln(os.Stderr, logLine(LevelWarn, msg))
}

func logError(format string, args ...interface{}) {
	msg := fmt.Sprintf(format, args...)
	fmt.Fprintln(os.Stderr, logLine(LevelError, msg))
}
GOEOF

