package main

import (
	"fmt"
	"strings"
)

// Option represents a CLI option definition
type Option struct {
	LongName    string
	ShortName   byte
	Description string
	HasValue    bool
	DefaultVal  string
	// For skip-able bool options like --[skip-]my-cnf
	Skippable   bool
	// Whether it has an optional value like --password[=value]
	OptionalVal bool
}

// ParsedOption holds parsed option value
type ParsedOption struct {
	Name  string
	Value string
	Set   bool
}

// OptionSet is a collection of options
type OptionSet struct {
	Options map[string]*Option
}

func NewOptionSet() *OptionSet {
	return &OptionSet{Options: make(map[string]*Option)}
}

func (os *OptionSet) Add(opt *Option) {
	os.Options[opt.LongName] = opt
}

// Global options shared across all commands
var globalOptions = []*Option{
	{LongName: "connect-options", ShortName: 'o', Description: "Comma-separated session options to set upon connecting to each database server", HasValue: true},
	{LongName: "debug", Description: "Enable debug logging"},
	{LongName: "help", ShortName: '?', Description: "Display usage information for the specified command", OptionalVal: true},
	{LongName: "host-wrapper", ShortName: 'H', Description: "External bin to shell out to for host lookup; see manual for template vars", HasValue: true},
	{LongName: "ignore-func", Description: "Ignore functions that match regex", HasValue: true},
	{LongName: "ignore-proc", Description: "Ignore stored procedures that match regex", HasValue: true},
	{LongName: "ignore-schema", Description: "Ignore schemas that match regex", HasValue: true},
	{LongName: "ignore-table", Description: "Ignore tables that match regex", HasValue: true},
	{LongName: "my-cnf", Description: "Parse ~/.my.cnf for configuration", Skippable: true},
	{LongName: "password", ShortName: 'p', Description: `Password for database user; omit value to prompt from TTY (default "$MYSQL_PWD")`, OptionalVal: true},
	{LongName: "ssl-mode", Description: `Specify desired connection security SSL/TLS usage (valid values: "disabled", "preferred", "required")`, HasValue: true},
	{LongName: "user", ShortName: 'u', Description: "Username to connect to database host", HasValue: true, DefaultVal: "root"},
	{LongName: "version", Description: "Display program version"},
}

// ParseArgs parses command-line arguments 
// Returns: options map, positional args, error
func ParseArgs(args []string, cmdOpts []*Option) (map[string]string, []string, error) {
	result := make(map[string]string)
	var positional []string

	// Build short-to-long mapping
	shortMap := make(map[byte]string)
	optsByLong := make(map[string]*Option)

	allOpts := append(globalOptions, cmdOpts...)
	for _, opt := range allOpts {
		optsByLong[opt.LongName] = opt
		if opt.ShortName != 0 {
			shortMap[opt.ShortName] = opt.LongName
		}
	}

	i := 0
	for i < len(args) {
		arg := args[i]
		if arg == "--" {
			positional = append(positional, args[i+1:]...)
			break
		}

		if strings.HasPrefix(arg, "--") {
			// Long option
			optStr := arg[2:]
			var optName, optVal string
			hasVal := false

			if eqIdx := strings.Index(optStr, "="); eqIdx >= 0 {
				optName = optStr[:eqIdx]
				optVal = optStr[eqIdx+1:]
				hasVal = true
			} else {
				optName = optStr
			}

			// Handle --skip- prefix
			skipPrefix := false
			if strings.HasPrefix(optName, "skip-") {
				skipPrefix = true
				optName = optName[5:]
			}

			opt, ok := optsByLong[optName]
			if !ok {
				return nil, nil, fmt.Errorf("CLI: Unknown option %q", optName)
			}

			if skipPrefix {
				if !opt.Skippable {
					return nil, nil, fmt.Errorf("CLI: Unknown option \"skip-%s\"", optName)
				}
				result[optName] = "false"
			} else if opt.HasValue || opt.OptionalVal {
				if hasVal {
					result[optName] = optVal
				} else if opt.OptionalVal {
					result[optName] = ""
				} else {
					// Need next arg as value
					if i+1 >= len(args) {
						return nil, nil, fmt.Errorf("CLI: Missing value for option --%s", optName)
					}
					i++
					result[optName] = args[i]
				}
			} else {
				// Boolean option
				if hasVal {
					return nil, nil, fmt.Errorf("CLI: Option --%s does not accept a value", optName)
				}
				result[optName] = "true"
			}
		} else if strings.HasPrefix(arg, "-") && len(arg) > 1 {
			// Short option(s)
			chars := arg[1:]
			for j := 0; j < len(chars); j++ {
				c := chars[j]
				longName, ok := shortMap[c]
				if !ok {
					return nil, nil, fmt.Errorf("CLI: Unknown option %q", string(c))
				}
				opt := optsByLong[longName]
				if opt.HasValue || opt.OptionalVal {
					// Rest of chars is the value, or next arg
					rest := chars[j+1:]
					if rest != "" {
						// Inline value: -pPASSWORD
						if strings.HasPrefix(rest, "=") {
							result[longName] = rest[1:]
						} else {
							result[longName] = rest
						}
					} else if opt.OptionalVal {
						result[longName] = ""
					} else {
						if i+1 >= len(args) {
							return nil, nil, fmt.Errorf("CLI: Missing value for option -%c", c)
						}
						i++
						result[longName] = args[i]
					}
					break // consumed rest of chars
				} else {
					result[longName] = "true"
				}
			}
		} else {
			positional = append(positional, arg)
		}
		i++
	}

	return result, positional, nil
}
GOEOF

