func ParseArgs(args []string, cmdOpts []*Option) (map[string]string, []string, error) {
	result := make(map[string]string)
	var positional []string

	// Build short-to-long mapping
	shortMap := make(map[byte]string)
	optsByLong := make(map[string]*Option)

	allOpts := append(globalOptions, cmdOpts...)
