				if hasVal {
					return nil, nil, fmt.Errorf("CLI: Option --%s does not accept a value", optName)
				}
				result[optName] = "true"
			}
		} else if strings.HasPrefix(arg, "-") && len(arg) > 1 {
			// Short option(s)
			chars := arg[1:]
			for j := 0; j < len(chars); j++ {
				c := chars[j]
				longName, ok := shortMap[c]
				if !ok {
					return nil, nil, fmt.Errorf("CLI: Unknown option %q", string(c))
				}
				opt := optsByLong[longName]
				if opt.HasValue || opt.OptionalVal {
					// Rest of chars is the value, or next arg
					rest := chars[j+1:]
					if rest != "" {
						// Inline value: -pPASSWORD
						if strings.HasPrefix(rest, "=") {
