package main

import (
	"bufio"
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

// Config represents merged configuration from .skeema files
type Config struct {
	// Values holds the effective option values for the current environment
	Values map[string]string
	// Dir is the directory this config applies to
	Dir string
}

// SkeemaFile represents a parsed .skeema file
type SkeemaFile struct {
	Path     string
	Sections map[string]map[string]string // section name -> key -> value
	// "" is the default/global section
}

// ParseSkeemaFile parses a .skeema config file
func ParseSkeemaFile(path string) (*SkeemaFile, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer f.Close()

	sf := &SkeemaFile{
		Path:     path,
		Sections: make(map[string]map[string]string),
	}
	sf.Sections[""] = make(map[string]string)

	currentSection := ""
	scanner := bufio.NewScanner(f)
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" || strings.HasPrefix(line, "#") || strings.HasPrefix(line, ";") {
			continue
		}
		if strings.HasPrefix(line, "[") && strings.HasSuffix(line, "]") {
			currentSection = line[1 : len(line)-1]
			if _, exists := sf.Sections[currentSection]; !exists {
				sf.Sections[currentSection] = make(map[string]string)
			}
			continue
		}
		// Key=value or key
		if eqIdx := strings.Index(line, "="); eqIdx >= 0 {
			key := strings.TrimSpace(line[:eqIdx])
			val := strings.TrimSpace(line[eqIdx+1:])
			sf.Sections[currentSection][key] = val
		} else {
			sf.Sections[currentSection][line] = "true"
		}
	}
	return sf, scanner.Err()
}

// WriteSkeemaFile writes a SkeemaFile back to disk
func WriteSkeemaFile(sf *SkeemaFile) error {
	f, err := os.Create(sf.Path)
	if err != nil {
		return err
	}
	defer f.Close()

	w := bufio.NewWriter(f)

	// Write global section first (no header)
	if globalSec, ok := sf.Sections[""]; ok {
		for k, v := range globalSec {
			if v == "true" {
				fmt.Fprintln(w, k)
			} else {
				fmt.Fprintf(w, "%s=%s\n", k, v)
			}
		}
	}

	// Write named sections in order they were added
	// We need to preserve order, so we use the SectionOrder
	for _, name := range sf.getSectionOrder() {
		if name == "" {
			continue
		}
		fmt.Fprintf(w, "\n[%s]\n", name)
		sec := sf.Sections[name]
		for k, v := range sec {
			if v == "true" {
				fmt.Fprintln(w, k)
			} else {
				fmt.Fprintf(w, "%s=%s\n", k, v)
			}
		}
	}

	return w.Flush()
}

// getSectionOrder returns the section names in insertion order
func (sf *SkeemaFile) getSectionOrder() []string {
	var order []string
	for name := range sf.Sections {
		if name != "" {
			order = append(order, name)
		}
	}
	return order
}

// SkeemaFileOrdered is a SkeemaFile that preserves section ordering
type SkeemaFileOrdered struct {
	Path         string
	GlobalKV     []KVPair
	Sections     []Section
}

type KVPair struct {
	Key   string
	Value string
}

type Section struct {
	Name string
	KV   []KVPair
}

func ParseSkeemaFileOrdered(path string) (*SkeemaFileOrdered, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer f.Close()

	sf := &SkeemaFileOrdered{Path: path}
	var currentSection *Section

	scanner := bufio.NewScanner(f)
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" || strings.HasPrefix(line, "#") || strings.HasPrefix(line, ";") {
			continue
		}
		if strings.HasPrefix(line, "[") && strings.HasSuffix(line, "]") {
			name := line[1 : len(line)-1]
			sf.Sections = append(sf.Sections, Section{Name: name})
			currentSection = &sf.Sections[len(sf.Sections)-1]
			continue
		}
		kv := parseKV(line)
		if currentSection == nil {
			sf.GlobalKV = append(sf.GlobalKV, kv)
		} else {
			currentSection.KV = append(currentSection.KV, kv)
		}
	}
	return sf, scanner.Err()
}

func parseKV(line string) KVPair {
	if eqIdx := strings.Index(line, "="); eqIdx >= 0 {
		return KVPair{
			Key:   strings.TrimSpace(line[:eqIdx]),
			Value: strings.TrimSpace(line[eqIdx+1:]),
		}
	}
	return KVPair{Key: strings.TrimSpace(line), Value: "true"}
}

func WriteSkeemaFileOrdered(sf *SkeemaFileOrdered) error {
	f, err := os.Create(sf.Path)
	if err != nil {
		return err
	}
	defer f.Close()

	w := bufio.NewWriter(f)

	for _, kv := range sf.GlobalKV {
		writeKV(w, kv)
	}

	for _, sec := range sf.Sections {
		if len(sf.GlobalKV) > 0 || sec.Name != sf.Sections[0].Name {
			fmt.Fprintln(w)
		}
		fmt.Fprintf(w, "[%s]\n", sec.Name)
		for _, kv := range sec.KV {
			writeKV(w, kv)
		}
	}

	return w.Flush()
}

func writeKV(w *bufio.Writer, kv KVPair) {
	if kv.Value == "true" {
		fmt.Fprintln(w, kv.Key)
	} else {
		fmt.Fprintf(w, "%s=%s\n", kv.Key, kv.Value)
	}
}

// GetEffectiveConfig returns the merged config for a directory and environment
// It walks up from the given dir to find and merge .skeema files
func GetEffectiveConfig(dir, environment string) (map[string]string, error) {
	config := make(map[string]string)

	// Find all .skeema files from root to dir
	var skeemaDirs []string
	path := filepath.Clean(dir)
	for {
		skeemaDirs = append([]string{path}, skeemaDirs...)
		parent := filepath.Dir(path)
		if parent == path {
			break
		}
		path = parent
	}

	for _, d := range skeemaDirs {
		skeemaPath := filepath.Join(d, ".skeema")
		if _, err := os.Stat(skeemaPath); os.IsNotExist(err) {
			continue
		}
		sf, err := ParseSkeemaFile(skeemaPath)
		if err != nil {
			return nil, err
		}

		// Apply global section
		for k, v := range sf.Sections[""] {
			config[k] = v
		}

		// Apply environment-specific section
		if environment != "" {
			if envSec, ok := sf.Sections[environment]; ok {
				for k, v := range envSec {
					config[k] = v
				}
			}
		}
	}

	return config, nil
}

// FindSkeemaFile looks for .skeema file in dir
func FindSkeemaFile(dir string) string {
	path := filepath.Join(dir, ".skeema")
	if _, err := os.Stat(path); err == nil {
		return path
	}
	return ""
}

// HasSkeemaFile returns true if dir has a .skeema file
func HasSkeemaFile(dir string) bool {
	return FindSkeemaFile(dir) != ""
}

// HasSchemaConfig returns true if the effective config for this directory
// defines a schema option
func HasSchemaConfig(config map[string]string) bool {
	_, ok := config["schema"]
	return ok
}

// HasHostConfig returns true if the effective config defines a host option
func HasHostConfig(config map[string]string) bool {
	_, ok := config["host"]
	return ok
}

// GetSkeemaFileDirConfig reads only the config from the .skeema file in a specific dir
// (not parent dirs), for a specific environment
func GetSkeemaFileDirConfig(dir, environment string) (map[string]string, error) {
	config := make(map[string]string)
	skeemaPath := filepath.Join(dir, ".skeema")
	if _, err := os.Stat(skeemaPath); os.IsNotExist(err) {
		return config, nil
	}
	sf, err := ParseSkeemaFile(skeemaPath)
	if err != nil {
		return nil, err
	}
	for k, v := range sf.Sections[""] {
		config[k] = v
	}
	if environment != "" {
		if envSec, ok := sf.Sections[environment]; ok {
			for k, v := range envSec {
				config[k] = v
			}
		}
	}
	return config, nil
}

// MergeConfig merges parent config with local config, local takes priority
func MergeConfig(parent, local map[string]string) map[string]string {
	result := make(map[string]string)
	for k, v := range parent {
		result[k] = v
	}
	for k, v := range local {
		result[k] = v
	}
	return result
}

// HasEnvironment checks if a .skeema file has a given environment section
func HasEnvironment(skeemaPath, envName string) bool {
	sf, err := ParseSkeemaFile(skeemaPath)
	if err != nil {
		return false
	}
	_, ok := sf.Sections[envName]
	return ok
}

// AddEnvironmentToFile adds a new environment section to a .skeema file
func AddEnvironmentToFile(skeemaPath, envName string, kvPairs []KVPair) error {
	sf, err := ParseSkeemaFileOrdered(skeemaPath)
	if err != nil {
		return err
	}

	// Check if exists
	for _, sec := range sf.Sections {
		if sec.Name == envName {
			return fmt.Errorf("Environment name %q already defined in %s", envName, skeemaPath)
		}
	}

	sf.Sections = append(sf.Sections, Section{
		Name: envName,
		KV:   kvPairs,
	})

	return WriteSkeemaFileOrdered(sf)
}

// Read my.cnf file
func ReadMyCNF() map[string]string {
	result := make(map[string]string)
	home, err := os.UserHomeDir()
	if err != nil {
		return result
	}
	path := filepath.Join(home, ".my.cnf")
	f, err := os.Open(path)
	if err != nil {
		return result
	}
	defer f.Close()

	inClient := false
	scanner := bufio.NewScanner(f)
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" || strings.HasPrefix(line, "#") || strings.HasPrefix(line, ";") {
			continue
		}
		if strings.HasPrefix(line, "[") && strings.HasSuffix(line, "]") {
			section := line[1 : len(line)-1]
			inClient = (section == "client" || section == "mysql")
			continue
		}
		if inClient {
			if eqIdx := strings.Index(line, "="); eqIdx >= 0 {
				key := strings.TrimSpace(line[:eqIdx])
				val := strings.TrimSpace(line[eqIdx+1:])
				result[key] = val
			}
		}
	}
	return result
}
