// MySQL protocol constants
const (
	// Capability flags
	clientLongPassword    = 0x00000001
	clientFoundRows       = 0x00000002
	clientLongFlag        = 0x00000004
	clientConnectWithDB   = 0x00000008
	clientNoSchema        = 0x00000010
	clientCompress        = 0x00000020
	clientODBC            = 0x00000040
	clientLocalFiles      = 0x00000080
	clientIgnoreSpace     = 0x00000100
	clientProtocol41      = 0x00000200
	clientInteractive     = 0x00000400
	clientSSL             = 0x00000800
	clientIgnoreSigpipe   = 0x00001000
	clientTransactions    = 0x00002000
	clientReserved        = 0x00004000
	clientSecureConn      = 0x00008000
	clientMultiStatements = 0x00010000
	clientMultiResults    = 0x00020000
	clientPSMultiResults  = 0x00040000
	clientPluginAuth      = 0x00080000
	clientConnectAttrs    = 0x00100000
	clientPluginAuthLenEncClientData = 0x00200000
	clientCanHandleExpiredPasswords  = 0x00400000
	clientSessionTrack    = 0x00800000
	clientDeprecateEOF    = 0x01000000

	// Command bytes
	comQuery = 0x03
	comPing  = 0x0E
	comQuit  = 0x01

	// Packet types
	okPacket  = 0x00
	eofPacket = 0xFE
	errPacket = 0xFF
)

// MySQLConn represents a connection to a MySQL server
type MySQLConn struct {
	conn        net.Conn
	seqNum      byte
	capabilities uint32
	serverVersion string
	serverFlavor  string // "mysql" or "mariadb"
	serverMajor   int
	serverMinor   int
	serverPatch   int
	charsetID     byte
	db            string
	user          string
	password      string
	authPlugin    string
}

// DSN holds connection parameters
type DSN struct {
	Host     string
	Port     int
	Socket   string
	User     string
	Password string
	DBName   string
	TLS      string // "disabled", "preferred", "required"
}

func (d *DSN) NetworkAddress() string {
	if d.Socket != "" && (d.Host == "" || d.Host == "localhost") {
		return d.Socket
	}
	port := d.Port
	if port == 0 {
		port = 3306
	}
	return fmt.Sprintf("%s:%d", d.Host, port)
}

func (d *DSN) Network() string {
	if d.Socket != "" && (d.Host == "" || d.Host == "localhost") {
		return "unix"
	}
	return "tcp"
}

func (d *DSN) DisplayAddress() string {
	if d.Network() == "unix" {
		return fmt.Sprintf("%s:%s", d.Host, d.Socket)
	}
	port := d.Port
	if port == 0 {
		port = 3306
	}
	return fmt.Sprintf("%s:%d", d.Host, port)
}

// Connect establishes a connection to MySQL
func Connect(dsn *DSN) (*MySQLConn, error) {
	var netConn net.Conn
	var err error

	network := dsn.Network()
	addr := dsn.NetworkAddress()

	if network == "unix" {
		netConn, err = net.Dial("unix", addr)
	} else {
		netConn, err = net.Dial("tcp", addr)
	}
	if err != nil {
		return nil, err
	}

	mc := &MySQLConn{
		conn:     netConn,
		user:     dsn.User,
		password: dsn.Password,
		db:       dsn.DBName,
	}

	// Read server greeting
	if err := mc.readHandshake(dsn); err != nil {
		netConn.Close()
		return nil, err
	}

	return mc, nil
}

func (mc *MySQLConn) readHandshake(dsn *DSN) error {
	// Read initial handshake packet
	pkt, err := mc.readPacket()
	if err != nil {
		return err
	}

	if len(pkt) < 1 {
		return fmt.Errorf("empty handshake packet")
	}

	// Packet type
	if pkt[0] == errPacket {
		return mc.parseError(pkt)
	}

	// Protocol version should be 10
	if pkt[0] != 10 {
		return fmt.Errorf("unexpected protocol version: %d", pkt[0])
	}

	// Parse server version string
	pos := 1
	end := strings.IndexByte(string(pkt[pos:]), 0)
	if end < 0 {
		return fmt.Errorf("malformed server version")
	}
	mc.serverVersion = string(pkt[pos : pos+end])
	pos += end + 1

	// Parse version numbers
	mc.parseVersion(mc.serverVersion)

	// Connection ID (4 bytes)
	pos += 4

	// Auth plugin data part 1 (8 bytes)
	authData := make([]byte, 8)
	copy(authData, pkt[pos:pos+8])
	pos += 8

	// Filler (1 byte)
	pos++

	// Capability flags lower (2 bytes)
	capLower := uint32(binary.LittleEndian.Uint16(pkt[pos:]))
	pos += 2

	// Character set
	mc.charsetID = pkt[pos]
	pos++

	// Status flags (2 bytes)
	pos += 2

	// Capability flags upper (2 bytes)
	capUpper := uint32(binary.LittleEndian.Uint16(pkt[pos:])) << 16
	pos += 2
	mc.capabilities = capLower | capUpper

	// Length of auth plugin data (1 byte)
	authDataLen := int(pkt[pos])
	pos++

	// Reserved (10 bytes)
	pos += 10

	// Auth plugin data part 2
	part2Len := authDataLen - 8
	if part2Len < 13 {
		part2Len = 13
	}
	if pos+part2Len <= len(pkt) {
		authData = append(authData, pkt[pos:pos+part2Len]...)
	}
	pos += part2Len

	// Auth plugin name
	if mc.capabilities&clientPluginAuth != 0 && pos < len(pkt) {
		end = strings.IndexByte(string(pkt[pos:]), 0)
		if end >= 0 {
			mc.authPlugin = string(pkt[pos : pos+end])
		} else {
			mc.authPlugin = string(pkt[pos:])
		}
	}

	if mc.authPlugin == "" {
		mc.authPlugin = "mysql_native_password"
	}

	// Handle TLS if required
	if dsn.TLS == "required" || dsn.TLS == "preferred" {
		if mc.capabilities&clientSSL != 0 {
			if err := mc.startTLS(); err != nil {
				if dsn.TLS == "required" {
					return fmt.Errorf("TLS required but handshake failed: %v", err)
				}
				// preferred: continue without TLS
			}
		} else if dsn.TLS == "required" {
			return fmt.Errorf("TLS required but server does not support it")
		}
	}

	// Send authentication response
	return mc.sendAuth(authData)
}

func (mc *MySQLConn) parseVersion(ver string) {
	// Could be "8.0.28" or "10.5.12-MariaDB"
	mc.serverFlavor = "mysql"
	if strings.Contains(strings.ToLower(ver), "mariadb") {
		mc.serverFlavor = "mariadb"
	}

	// Find version prefix (before any dash)
	verPart := ver
	if idx := strings.Index(ver, "-"); idx >= 0 {
		verPart = ver[:idx]
	}
	// But MariaDB may start with "10.x.y" or "5.5"

	parts := strings.Split(verPart, ".")
	if len(parts) >= 1 {
		fmt.Sscanf(parts[0], "%d", &mc.serverMajor)
	}
	if len(parts) >= 2 {
		fmt.Sscanf(parts[1], "%d", &mc.serverMinor)
	}
	if len(parts) >= 3 {
		fmt.Sscanf(parts[2], "%d", &mc.serverPatch)
	}
}

func (mc *MySQLConn) startTLS() error {
	// Send SSL request packet
	capFlags := uint32(clientSSL | clientProtocol41 | clientLongPassword | clientTransactions |
		clientSecureConn | clientPluginAuth | clientDeprecateEOF)

	pkt := make([]byte, 32)
	binary.LittleEndian.PutUint32(pkt[0:], capFlags)
	binary.LittleEndian.PutUint32(pkt[4:], 0x40000000)
	pkt[8] = 33 // utf8mb4

	if err := mc.writePacket(pkt); err != nil {
		return err
	}

	// Upgrade to TLS
	tlsConf := &tls.Config{
		InsecureSkipVerify: true,
	}
	tlsConn := tls.Client(mc.conn, tlsConf)
	if err := tlsConn.Handshake(); err != nil {
		return err
	}
	mc.conn = tlsConn
	return nil
}

func (mc *MySQLConn) sendAuth(authData []byte) error {
	// Build auth response
	var authResp []byte

	switch mc.authPlugin {
	case "mysql_native_password":
		authResp = nativePasswordAuth(mc.password, authData[:20])
	case "caching_sha2_password":
		authResp = sha2PasswordAuth(mc.password, authData[:20])
	case "mysql_clear_password":
		authResp = append([]byte(mc.password), 0)
	default:
		authResp = nativePasswordAuth(mc.password, authData[:20])
	}

	// Build handshake response packet
	capFlags := uint32(clientLongPassword | clientFoundRows | clientLongFlag |
		clientProtocol41 | clientTransactions | clientSecureConn |
		clientPluginAuth | clientMultiStatements | clientMultiResults |
		clientDeprecateEOF)

	if mc.db != "" {
		capFlags |= clientConnectWithDB
	}

	pktLen := 4 + 4 + 1 + 23 + len(mc.user) + 1 + 1 + len(authResp) + len(mc.authPlugin) + 1
	if mc.db != "" {
		pktLen += len(mc.db) + 1
	}

	pkt := make([]byte, pktLen)
	pos := 0

	// Capability flags
	binary.LittleEndian.PutUint32(pkt[pos:], capFlags)
	pos += 4

	// Max packet size
	binary.LittleEndian.PutUint32(pkt[pos:], 0x40000000)
	pos += 4

	// Character set (utf8mb4)
	pkt[pos] = 33
	pos++

	// 23 reserved bytes
	pos += 23

	// Username (null-terminated)
	copy(pkt[pos:], mc.user)
	pos += len(mc.user)
	pkt[pos] = 0
	pos++

	// Auth response length + data
	pkt[pos] = byte(len(authResp))
	pos++
	copy(pkt[pos:], authResp)
	pos += len(authResp)

	// Database name (if set)
	if mc.db != "" {
		copy(pkt[pos:], mc.db)
		pos += len(mc.db)
		pkt[pos] = 0
		pos++
	}

	// Auth plugin name
	copy(pkt[pos:], mc.authPlugin)
	pos += len(mc.authPlugin)
	pkt[pos] = 0

	if err := mc.writePacket(pkt); err != nil {
		return err
	}

	// Read auth result
	return mc.readAuthResult()
}

func (mc *MySQLConn) readAuthResult() error {
	pkt, err := mc.readPacket()
	if err != nil {
		return err
	}
	if len(pkt) == 0 {
		return fmt.Errorf("empty auth response")
	}

	switch pkt[0] {
	case okPacket:
		return nil
	case errPacket:
		return mc.parseError(pkt)
	case 0x01:
		// Auth switch: more auth needed
		return mc.handleAuthSwitch(pkt)
	case 0xFE:
		// Auth switch request
		return mc.handleAuthSwitch(pkt)
	default:
		return fmt.Errorf("unexpected auth response: 0x%02x", pkt[0])
	}
}

func (mc *MySQLConn) handleAuthSwitch(pkt []byte) error {
	// Handle auth switch request
	if len(pkt) < 1 {
		return fmt.Errorf("empty auth switch packet")
	}

	// Try to continue with password
	var authResp []byte
	if len(pkt) > 1 {
		pos := 1
		end := strings.IndexByte(string(pkt[pos:]), 0)
		if end >= 0 {
			pluginName := string(pkt[pos : pos+end])
			pos += end + 1
			authData := pkt[pos:]
			switch pluginName {
			case "mysql_native_password":
				authResp = nativePasswordAuth(mc.password, authData)
			case "caching_sha2_password":
				if mc.password == "" {
					authResp = []byte{}
				} else {
					authResp = sha2PasswordAuth(mc.password, authData)
				}
			default:
				authResp = nativePasswordAuth(mc.password, authData)
			}
		}
	}

	if err := mc.writePacket(authResp); err != nil {
		return err
	}

	// Read result
	rpkt, err := mc.readPacket()
	if err != nil {
		return err
	}
	if len(rpkt) == 0 {
		return fmt.Errorf("empty auth result")
	}
	switch rpkt[0] {
	case okPacket:
		return nil
	case errPacket:
		return mc.parseError(rpkt)
	case 0x01:
		// caching_sha2_password: need to send full password
		// 0x03 = fast auth failed, send plaintext
		if len(rpkt) >= 2 && rpkt[1] == 0x04 {
			// Full auth required - send plaintext
			if err := mc.writePacket(append([]byte(mc.password), 0)); err != nil {
				return err
			}
			rpkt2, err := mc.readPacket()
			if err != nil {
				return err
			}
			if len(rpkt2) > 0 && rpkt2[0] == okPacket {
				return nil
			}
			if len(rpkt2) > 0 && rpkt2[0] == errPacket {
				return mc.parseError(rpkt2)
			}
		}
		return nil
	default:
		return fmt.Errorf("unexpected auth switch result: 0x%02x", rpkt[0])
	}
}

func nativePasswordAuth(password string, scramble []byte) []byte {
	if password == "" {
		return []byte{}
	}
	// SHA1(password) XOR SHA1(scramble + SHA1(SHA1(password)))
	hash1 := sha1.Sum([]byte(password))
	hash2 := sha1.Sum(hash1[:])

	h := sha1.New()
	h.Write(scramble)
	h.Write(hash2[:])
	hash3 := h.Sum(nil)

	result := make([]byte, 20)
	for i := range result {
		result[i] = hash1[i] ^ hash3[i]
	}
	return result
}

func sha2PasswordAuth(password string, scramble []byte) []byte {
	if password == "" {
		return []byte{}
	}
	// XOR(SHA256(password), SHA256(SHA256(SHA256(password)), nonce))
	h1 := sha256.Sum256([]byte(password))
	h2 := sha256.Sum256(h1[:])

	h := sha256.New()
	h.Write(h2[:])
	h.Write(scramble)
	h3 := h.Sum(nil)

	result := make([]byte, 32)
	for i := range result {
		result[i] = h1[i] ^ h3[i]
	}
	return result
}

func (mc *MySQLConn) parseError(pkt []byte) error {
	if len(pkt) < 3 {
		return fmt.Errorf("malformed error packet")
	}
	// Skip error flag (1), error code (2)
	pos := 3
	if len(pkt) > 3 && pkt[3] == '#' {
		// SQL state (6 bytes: '#' + 5 chars)
		pos += 6
	}
	if pos < len(pkt) {
		return fmt.Errorf("%s", string(pkt[pos:]))
	}
	return fmt.Errorf("unknown MySQL error")
}

// readPacket reads a MySQL protocol packet
func (mc *MySQLConn) readPacket() ([]byte, error) {
	// Read 4-byte header
	header := make([]byte, 4)
	if _, err := io.ReadFull(mc.conn, header); err != nil {
		return nil, err
	}

	// Payload length is 3 bytes LE
	payloadLen := int(header[0]) | int(header[1])<<8 | int(header[2])<<16
	mc.seqNum = header[3] + 1

	if payloadLen == 0 {
		return []byte{}, nil
	}

	payload := make([]byte, payloadLen)
	if _, err := io.ReadFull(mc.conn, payload); err != nil {
		return nil, err
	}

	return payload, nil
}

// writePacket writes a MySQL protocol packet
func (mc *MySQLConn) writePacket(payload []byte) error {
	pktLen := len(payload)
	header := []byte{
		byte(pktLen),
		byte(pktLen >> 8),
		byte(pktLen >> 16),
		mc.seqNum,
	}
	mc.seqNum++

	if _, err := mc.conn.Write(header); err != nil {
		return err
	}
	if len(payload) > 0 {
		if _, err := mc.conn.Write(payload); err != nil {
			return err
		}
	}
	return nil
}

// Query executes a query and returns results
type QueryResult struct {
	Columns []string
	Rows    [][]string
}

func (mc *MySQLConn) Query(query string) (*QueryResult, error) {
	mc.seqNum = 0
	pkt := make([]byte, len(query)+1)
	pkt[0] = comQuery
	copy(pkt[1:], query)

	if err := mc.writePacket(pkt); err != nil {
		return nil, err
	}

	// Read response
	resp, err := mc.readPacket()
	if err != nil {
		return nil, err
	}

	if len(resp) == 0 {
		return nil, fmt.Errorf("empty query response")
	}

	switch resp[0] {
	case okPacket:
		return &QueryResult{}, nil
	case errPacket:
		return nil, mc.parseError(resp)
	case 0xFB:
		return nil, fmt.Errorf("LOCAL INFILE not supported")
	}

	// Result set - first packet has column count
	colCount, _ := readLenEnc(resp, 0)

	result := &QueryResult{}

	// Read column definitions
	for i := 0; i < int(colCount); i++ {
		colPkt, err := mc.readPacket()
		if err != nil {
			return nil, err
		}
		// Parse column name from column definition packet
		pos := 0
		// catalog
		n, pos := skipLenEncStr(colPkt, pos)
		_ = n
		// db
		n, pos = skipLenEncStr(colPkt, pos)
		_ = n
		// table
		n, pos = skipLenEncStr(colPkt, pos)
		_ = n
		// org_table
		n, pos = skipLenEncStr(colPkt, pos)
		_ = n
		// name
		nameLen, namePos := readLenEnc(colPkt, pos)
		colName := ""
		if namePos+int(nameLen) <= len(colPkt) {
			colName = string(colPkt[namePos : namePos+int(nameLen)])
		}
		result.Columns = append(result.Columns, colName)
	}

	// Read EOF packet (if not CLIENT_DEPRECATE_EOF)
	if mc.capabilities&clientDeprecateEOF == 0 {
		_, err = mc.readPacket()
		if err != nil {
			return nil, err
		}
	}

	// Read rows
	for {
		rowPkt, err := mc.readPacket()
		if err != nil {
			return nil, err
		}

		if len(rowPkt) == 0 {
			break
		}

		// Check for EOF or OK packet
		if rowPkt[0] == eofPacket && len(rowPkt) < 9 {
			break
		}
		if rowPkt[0] == okPacket && mc.capabilities&clientDeprecateEOF != 0 {
			break
		}
		if rowPkt[0] == errPacket {
			return nil, mc.parseError(rowPkt)
		}

		// Parse row
		row := make([]string, len(result.Columns))
		pos := 0
		for j := range row {
			if pos >= len(rowPkt) {
				break
			}
			if rowPkt[pos] == 0xFB {
				// NULL
				row[j] = ""
				pos++
			} else {
				strLen, strPos := readLenEnc(rowPkt, pos)
				endPos := strPos + int(strLen)
				if endPos > len(rowPkt) {
					endPos = len(rowPkt)
				}
				row[j] = string(rowPkt[strPos:endPos])
				pos = endPos
			}
		}
		result.Rows = append(result.Rows, row)
	}

	return result, nil
}

// Exec executes a query without returning results
func (mc *MySQLConn) Exec(query string) error {
	_, err := mc.Query(query)
	return err
}

// Ping tests the connection
func (mc *MySQLConn) Ping() error {
	mc.seqNum = 0
	if err := mc.writePacket([]byte{comPing}); err != nil {
		return err
	}
	pkt, err := mc.readPacket()
	if err != nil {
		return err
	}
	if len(pkt) > 0 && pkt[0] == errPacket {
		return mc.parseError(pkt)
	}
	return nil
}

// Close closes the connection
func (mc *MySQLConn) Close() {
	mc.seqNum = 0
	mc.writePacket([]byte{comQuit})
	mc.conn.Close()
}

// UseDatabase selects a database
func (mc *MySQLConn) UseDatabase(db string) error {
	mc.seqNum = 0
	pkt := make([]byte, len(db)+2)
	pkt[0] = 0x02 // COM_INIT_DB
	copy(pkt[1:], db)
	if err := mc.writePacket(pkt); err != nil {
		return err
	}
	resp, err := mc.readPacket()
	if err != nil {
		return err
	}
	if len(resp) > 0 && resp[0] == errPacket {
		return mc.parseError(resp)
	}
	mc.db = db
	return nil
}

// GetDatabases returns a list of databases
func (mc *MySQLConn) GetDatabases() ([]string, error) {
	result, err := mc.Query("SHOW DATABASES")
	if err != nil {
		return nil, err
	}
	var dbs []string
	for _, row := range result.Rows {
		if len(row) > 0 {
			dbs = append(dbs, row[0])
		}
	}
	return dbs, nil
}

// GetServerFlavor returns a string identifying the server flavor and version
func (mc *MySQLConn) GetServerFlavor() string {
	if mc.serverVersion == "" {
		return ""
	}
	if mc.serverFlavor == "mariadb" {
		return fmt.Sprintf("mariadb:%d.%d", mc.serverMajor, mc.serverMinor)
	}
	return fmt.Sprintf("mysql:%d.%d", mc.serverMajor, mc.serverMinor)
}

// readLenEnc reads a length-encoded integer
func readLenEnc(data []byte, pos int) (uint64, int) {
	if pos >= len(data) {
		return 0, pos
	}
	b := data[pos]
	pos++
	if b < 0xFB {
		return uint64(b), pos
	}
	switch b {
	case 0xFC:
		if pos+2 > len(data) {
			return 0, pos
		}
		v := uint64(data[pos]) | uint64(data[pos+1])<<8
		return v, pos + 2
	case 0xFD:
		if pos+3 > len(data) {
			return 0, pos
		}
		v := uint64(data[pos]) | uint64(data[pos+1])<<8 | uint64(data[pos+2])<<16
		return v, pos + 3
	case 0xFE:
		if pos+8 > len(data) {
			return 0, pos
		}
		v := binary.LittleEndian.Uint64(data[pos:])
		return v, pos + 8
	}
	return 0, pos
}

func skipLenEncStr(data []byte, pos int) (int, int) {
	n, newPos := readLenEnc(data, pos)
	return int(n), newPos + int(n)
}

// ConnectFromConfig creates a MySQL connection from config map
func ConnectFromConfig(config map[string]string, opts map[string]string) (*MySQLConn, error) {
	dsn := DSNFromConfig(config, opts)
	return Connect(dsn)
}

// DSNFromConfig creates a DSN from a config map
func DSNFromConfig(config map[string]string, opts map[string]string) *DSN {
	dsn := &DSN{}

	if host, ok := config["host"]; ok {
		dsn.Host = host
	}
	if port, ok := config["port"]; ok {
		fmt.Sscanf(port, "%d", &dsn.Port)
	}
	if socket, ok := config["socket"]; ok {
		dsn.Socket = socket
	}

	// User - check opts first, then config, then default
	if user, ok := opts["user"]; ok && user != "" {
		dsn.User = user
	} else if user, ok := config["user"]; ok && user != "" {
		dsn.User = user
	} else {
		dsn.User = "root"
	}

	// Password
	if pwd, ok := opts["password"]; ok {
		dsn.Password = pwd
	} else if pwd, ok := config["password"]; ok {
		dsn.Password = pwd
	} else {
		// Check MYSQL_PWD env
		dsn.Password = os.Getenv("MYSQL_PWD")
	}

	if db, ok := config["schema"]; ok {
		dsn.DBName = db
	}

	if sslMode, ok := config["ssl-mode"]; ok {
		dsn.TLS = sslMode
	}
	if sslMode, ok := opts["ssl-mode"]; ok {
		dsn.TLS = sslMode
	}

	// Set socket default for localhost when no port specified
	if dsn.Host == "localhost" && dsn.Port == 0 && dsn.Socket == "" {
		// Check if socket is configured
		if socket, ok := config["socket"]; ok {
			dsn.Socket = socket
		} else {
			dsn.Socket = "/tmp/mysql.sock"
		}
	}

	return dsn
}
