// Connect establishes a connection to MySQL
func Connect(dsn *DSN) (*MySQLConn, error) {
	var netConn net.Conn
	var err error

	network := dsn.Network()
	addr := dsn.NetworkAddress()

	if network == "unix" {
		netConn, err = net.Dial("unix", addr)
	} else {
		netConn, err = net.Dial("tcp", addr)
	}
	if err != nil {
		return nil, err
	}

	mc := &MySQLConn{
		conn:     netConn,
		user:     dsn.User,
		password: dsn.Password,
		db:       dsn.DBName,
	}

