	pos := 1
	end := strings.IndexByte(string(pkt[pos:]), 0)
	if end < 0 {
		return fmt.Errorf("malformed server version")
	}
	mc.serverVersion = string(pkt[pos : pos+end])
	pos += end + 1

	// Parse version numbers
	mc.parseVersion(mc.serverVersion)

	// Connection ID (4 bytes)
	pos += 4

	// Auth plugin data part 1 (8 bytes)
	authData := make([]byte, 8)
	copy(authData, pkt[pos:pos+8])
	pos += 8

	// Filler (1 byte)
	pos++

	// Capability flags lower (2 bytes)
	capLower := uint32(binary.LittleEndian.Uint16(pkt[pos:]))
	pos += 2

	// Character set
	mc.charsetID = pkt[pos]
	pos++

	// Status flags (2 bytes)
	pos += 2

	// Capability flags upper (2 bytes)
	capUpper := uint32(binary.LittleEndian.Uint16(pkt[pos:])) << 16
	pos += 2
	mc.capabilities = capLower | capUpper

	// Length of auth plugin data (1 byte)
	authDataLen := int(pkt[pos])
	pos++

	// Reserved (10 bytes)
	pos += 10

	// Auth plugin data part 2
	part2Len := authDataLen - 8
	if part2Len < 13 {
		part2Len = 13
	}
	if pos+part2Len <= len(pkt) {
		authData = append(authData, pkt[pos:pos+part2Len]...)
	}
	pos += part2Len

	// Auth plugin name
	if mc.capabilities&clientPluginAuth != 0 && pos < len(pkt) {
		end = strings.IndexByte(string(pkt[pos:]), 0)
		if end >= 0 {
			mc.authPlugin = string(pkt[pos : pos+end])
		} else {
			mc.authPlugin = string(pkt[pos:])
		}
	}

	if mc.authPlugin == "" {
		mc.authPlugin = "mysql_native_password"
	}

	// Handle TLS if required
	if dsn.TLS == "required" || dsn.TLS == "preferred" {
		if mc.capabilities&clientSSL != 0 {
			if err := mc.startTLS(); err != nil {
				if dsn.TLS == "required" {
					return fmt.Errorf("TLS required but handshake failed: %v", err)
				}
				// preferred: continue without TLS
			}
		} else if dsn.TLS == "required" {
			return fmt.Errorf("TLS required but server does not support it")
