func nativePasswordAuth(password string, scramble []byte) []byte {
	if password == "" {
		return []byte{}
	}
	// SHA1(password) XOR SHA1(scramble + SHA1(SHA1(password)))
	hash1 := sha1.Sum([]byte(password))
	hash2 := sha1.Sum(hash1[:])

	h := sha1.New()
	h.Write(scramble)
	h.Write(hash2[:])
	hash3 := h.Sum(nil)

	result := make([]byte, 20)
	for i := range result {
		result[i] = hash1[i] ^ hash3[i]
	}
	return result
}

func sha2PasswordAuth(password string, scramble []byte) []byte {
	if password == "" {
		return []byte{}
	}
	// XOR(SHA256(password), SHA256(SHA256(SHA256(password)), nonce))
	h1 := sha256.Sum256([]byte(password))
	h2 := sha256.Sum256(h1[:])

	h := sha256.New()
	h.Write(h2[:])
	h.Write(scramble)
	h3 := h.Sum(nil)

	result := make([]byte, 32)
	for i := range result {
		result[i] = h1[i] ^ h3[i]
	}
	return result
}

func (mc *MySQLConn) parseError(pkt []byte) error {
	if len(pkt) < 3 {
		return fmt.Errorf("malformed error packet")
	}
	// Skip error flag (1), error code (2)
	pos := 3
	if len(pkt) > 3 && pkt[3] == '#' {
		// SQL state (6 bytes: '#' + 5 chars)
		pos += 6
	}
	if pos < len(pkt) {
		return fmt.Errorf("%s", string(pkt[pos:]))
	}
	return fmt.Errorf("unknown MySQL error")
}

// readPacket reads a MySQL protocol packet
func (mc *MySQLConn) readPacket() ([]byte, error) {
	// Read 4-byte header
	header := make([]byte, 4)
	if _, err := io.ReadFull(mc.conn, header); err != nil {
		return nil, err
	}

	// Payload length is 3 bytes LE
	payloadLen := int(header[0]) | int(header[1])<<8 | int(header[2])<<16
	mc.seqNum = header[3] + 1

	if payloadLen == 0 {
		return []byte{}, nil
	}

	payload := make([]byte, payloadLen)
	if _, err := io.ReadFull(mc.conn, payload); err != nil {
		return nil, err
	}

	return payload, nil
}

// writePacket writes a MySQL protocol packet
func (mc *MySQLConn) writePacket(payload []byte) error {
	pktLen := len(payload)
	header := []byte{
		byte(pktLen),
		byte(pktLen >> 8),
		byte(pktLen >> 16),
		mc.seqNum,
	}
	mc.seqNum++

	if _, err := mc.conn.Write(header); err != nil {
		return err
	}
	if len(payload) > 0 {
		if _, err := mc.conn.Write(payload); err != nil {
			return err
		}
	}
	return nil
}

// Query executes a query and returns results
type QueryResult struct {
	Columns []string
	Rows    [][]string
}

func (mc *MySQLConn) Query(query string) (*QueryResult, error) {
	mc.seqNum = 0
	pkt := make([]byte, len(query)+1)
	pkt[0] = comQuery
	copy(pkt[1:], query)

	if err := mc.writePacket(pkt); err != nil {
		return nil, err
	}

	// Read response
	resp, err := mc.readPacket()
	if err != nil {
		return nil, err
	}

	if len(resp) == 0 {
		return nil, fmt.Errorf("empty query response")
	}

	switch resp[0] {
	case okPacket:
		return &QueryResult{}, nil
	case errPacket:
		return nil, mc.parseError(resp)
	case 0xFB:
		return nil, fmt.Errorf("LOCAL INFILE not supported")
	}

	// Result set - first packet has column count
	colCount, _ := readLenEnc(resp, 0)

	result := &QueryResult{}

	// Read column definitions
	for i := 0; i < int(colCount); i++ {
		colPkt, err := mc.readPacket()
		if err != nil {
			return nil, err
		}
		// Parse column name from column definition packet
		pos := 0
		// catalog
		n, pos := skipLenEncStr(colPkt, pos)
		_ = n
		// db
		n, pos = skipLenEncStr(colPkt, pos)
		_ = n
		// table
		n, pos = skipLenEncStr(colPkt, pos)
		_ = n
		// org_table
		n, pos = skipLenEncStr(colPkt, pos)
		_ = n
		// name
		nameLen, namePos := readLenEnc(colPkt, pos)
		colName := ""
		if namePos+int(nameLen) <= len(colPkt) {
			colName = string(colPkt[namePos : namePos+int(nameLen)])
		}
		result.Columns = append(result.Columns, colName)
	}

	// Read EOF packet (if not CLIENT_DEPRECATE_EOF)
	if mc.capabilities&clientDeprecateEOF == 0 {
		_, err = mc.readPacket()
		if err != nil {
			return nil, err
		}
	}

	// Read rows
	for {
		rowPkt, err := mc.readPacket()
		if err != nil {
			return nil, err
		}

		if len(rowPkt) == 0 {
			break
		}

		// Check for EOF or OK packet
		if rowPkt[0] == eofPacket && len(rowPkt) < 9 {
			break
		}
		if rowPkt[0] == okPacket && mc.capabilities&clientDeprecateEOF != 0 {
			break
		}
		if rowPkt[0] == errPacket {
			return nil, mc.parseError(rowPkt)
		}

		// Parse row
		row := make([]string, len(result.Columns))
		pos := 0
		for j := range row {
			if pos >= len(rowPkt) {
				break
			}
			if rowPkt[pos] == 0xFB {
				// NULL
				row[j] = ""
				pos++
			} else {
				strLen, strPos := readLenEnc(rowPkt, pos)
				endPos := strPos + int(strLen)
				if endPos > len(rowPkt) {
					endPos = len(rowPkt)
				}
				row[j] = string(rowPkt[strPos:endPos])
				pos = endPos
			}
		}
		result.Rows = append(result.Rows, row)
	}

	return result, nil
}

// Exec executes a query without returning results
func (mc *MySQLConn) Exec(query string) error {
	_, err := mc.Query(query)
	return err
}

// Ping tests the connection
func (mc *MySQLConn) Ping() error {
	mc.seqNum = 0
	if err := mc.writePacket([]byte{comPing}); err != nil {
		return err
	}
	pkt, err := mc.readPacket()
	if err != nil {
		return err
	}
	if len(pkt) > 0 && pkt[0] == errPacket {
		return mc.parseError(pkt)
	}
	return nil
}

// Close closes the connection
func (mc *MySQLConn) Close() {
	mc.seqNum = 0
	mc.writePacket([]byte{comQuit})
	mc.conn.Close()
}

// UseDatabase selects a database
func (mc *MySQLConn) UseDatabase(db string) error {
	mc.seqNum = 0
	pkt := make([]byte, len(db)+2)
	pkt[0] = 0x02 // COM_INIT_DB
	copy(pkt[1:], db)
	if err := mc.writePacket(pkt); err != nil {
		return err
	}
	resp, err := mc.readPacket()
	if err != nil {
		return err
	}
	if len(resp) > 0 && resp[0] == errPacket {
		return mc.parseError(resp)
	}
	mc.db = db
	return nil
}

// GetDatabases returns a list of databases
func (mc *MySQLConn) GetDatabases() ([]string, error) {
	result, err := mc.Query("SHOW DATABASES")
	if err != nil {
		return nil, err
	}
	var dbs []string
	for _, row := range result.Rows {
		if len(row) > 0 {
			dbs = append(dbs, row[0])
		}
	}
	return dbs, nil
}

// GetServerFlavor returns a string identifying the server flavor and version
func (mc *MySQLConn) GetServerFlavor() string {
	if mc.serverVersion == "" {
		return ""
	}
	if mc.serverFlavor == "mariadb" {
		return fmt.Sprintf("mariadb:%d.%d", mc.serverMajor, mc.serverMinor)
	}
	return fmt.Sprintf("mysql:%d.%d", mc.serverMajor, mc.serverMinor)
}

// readLenEnc reads a length-encoded integer
func readLenEnc(data []byte, pos int) (uint64, int) {
	if pos >= len(data) {
		return 0, pos
	}
	b := data[pos]
	pos++
	if b < 0xFB {
		return uint64(b), pos
	}
	switch b {
	case 0xFC:
		if pos+2 > len(data) {
			return 0, pos
		}
		v := uint64(data[pos]) | uint64(data[pos+1])<<8
		return v, pos + 2
	case 0xFD:
		if pos+3 > len(data) {
			return 0, pos
		}
		v := uint64(data[pos]) | uint64(data[pos+1])<<8 | uint64(data[pos+2])<<16
		return v, pos + 3
	case 0xFE:
		if pos+8 > len(data) {
			return 0, pos
		}
		v := binary.LittleEndian.Uint64(data[pos:])
		return v, pos + 8
	}
	return 0, pos
}

func skipLenEncStr(data []byte, pos int) (int, int) {
	n, newPos := readLenEnc(data, pos)
	return int(n), newPos + int(n)
}

// ConnectFromConfig creates a MySQL connection from config map
func ConnectFromConfig(config map[string]string, opts map[string]string) (*MySQLConn, error) {
	dsn := DSNFromConfig(config, opts)
	return Connect(dsn)
}

// DSNFromConfig creates a DSN from a config map
func DSNFromConfig(config map[string]string, opts map[string]string) *DSN {
	dsn := &DSN{}

	if host, ok := config["host"]; ok {
		dsn.Host = host
	}
	if port, ok := config["port"]; ok {
		fmt.Sscanf(port, "%d", &dsn.Port)
	}
	if socket, ok := config["socket"]; ok {
		dsn.Socket = socket
	}

	// User - check opts first, then config, then default
	if user, ok := opts["user"]; ok && user != "" {
		dsn.User = user
	} else if user, ok := config["user"]; ok && user != "" {
		dsn.User = user
	} else {
		dsn.User = "root"
	}

	// Password
	if pwd, ok := opts["password"]; ok {
		dsn.Password = pwd
	} else if pwd, ok := config["password"]; ok {
		dsn.Password = pwd
	} else {
		// Check MYSQL_PWD env
		dsn.Password = os.Getenv("MYSQL_PWD")
	}

	if db, ok := config["schema"]; ok {
		dsn.DBName = db
	}

	if sslMode, ok := config["ssl-mode"]; ok {
		dsn.TLS = sslMode
	}
	if sslMode, ok := opts["ssl-mode"]; ok {
		dsn.TLS = sslMode
	}

	// Set socket default for localhost when no port specified
	if dsn.Host == "localhost" && dsn.Port == 0 && dsn.Socket == "" {
		// Check if socket is configured
		if socket, ok := config["socket"]; ok {
			dsn.Socket = socket
		} else {
			dsn.Socket = "/tmp/mysql.sock"
		}
	}

	return dsn
}
