	if !exists {
		logError("Unknown command %q", cmdName)
		return ExitFatalUsage
	}

	// Parse command-specific options
	// Re-parse all args with command options included
	allOpts, allPositional, err := ParseArgs(args, cmd.Options)
	if err != nil {
		logError("%s", err.Error())
		return ExitFatalUsage
	}

	// Re-enable debug mode if set
	if _, ok := allOpts["debug"]; ok {
		debugMode = true
	}

	// Warn about deprecated --my-cnf / --skip-my-cnf
	if _, ok := allOpts["my-cnf"]; ok {
		logWarn("Option --my-cnf is deprecated. This option will be removed in Skeema v2, and .my.cnf will always be parsed, with additional safety logic already in place. For more information, visit https://www.skeema.io/v2-changes")
	}

	// Remove command name from positional
	var cmdPositional []string
	for _, a := range allPositional {
		if a == cmdName {
			continue
		}
		cmdPositional = append(cmdPositional, a)
	}
	_ = cmdArgs

	// Handle help for this command
	if helpVal, ok := allOpts["help"]; ok {
		if helpVal == "" || helpVal == "true" {
			if cmd.Name == "version" {
				fmt.Println(versionString())
				return ExitSuccess
			}
			if cmd.Name == "help" {
				app.printHelp(allOpts)
				return ExitSuccess
			}
			cmd.printHelp()
			return ExitSuccess
		}
		// help=some-command
		helpCmd, exists := app.commands[helpVal]
		if !exists {
			logError("Unknown command %q", helpVal)
			return ExitFatalUsage
		}
		if helpCmd.Name == "version" {
			fmt.Println(versionString())
			return ExitSuccess
		}
		if helpCmd.Name == "help" {
			app.printHelp(allOpts)
			return ExitSuccess
		}
		helpCmd.printHelp()
		return ExitSuccess
	}

	// Handle --version flag
	if _, ok := allOpts["version"]; ok {
		fmt.Println(versionString())
		if debugMode {
			logDebug("Exit code 0 (SUCCESS)")
		}
		return ExitSuccess
	}

	// Check arg count
	if cmd.MaxArgs >= 0 && len(cmdPositional) > cmd.MaxArgs {
		logError("Extra command-line arg %q supplied; command %s takes a max of %d args", cmdPositional[cmd.MaxArgs], cmdName, cmd.MaxArgs)
		return ExitFatalUsage
	}
	if len(cmdPositional) < cmd.MinArgs {
		logError("Too few positional args supplied on command line; command %s requires at least %d args", cmdName, cmd.MinArgs)
		return ExitFatalUsage
	}

	// Check for forbidden options (host/schema for commands that don't accept them)
	if err := checkForbiddenOptions(cmd, allOpts); err != nil {
		logError("%s", err.Error())
		return ExitFatalUsage
	}

	exitCode := cmd.Run(cmdPositional, allOpts)
	if debugMode {
		if exitCode == 0 {
			logDebug("Exit code 0 (SUCCESS)")
		} else {
			logDebug("Exit code %d", exitCode)
		}
	}
	return exitCode
}

// Commands that don't allow host/schema to be set on CLI
var forbiddenCLIOptions = map[string][]string{
	"diff":   {"host", "schema"},
	"push":   {"host", "schema"},
	"pull":   {"host", "schema"},
	"format": {"host", "schema"},
	"lint":   {"host", "schema"},
}

func checkForbiddenOptions(cmd *Command, opts map[string]string) error {
	forbidden, ok := forbiddenCLIOptions[cmd.Name]
	if !ok {
		return nil
	}
	// We need to check if they were set on the command line (not from config)
	// Since we only parse CLI opts here, any value in opts was from CLI
	for _, optName := range forbidden {
		if _, ok := opts[optName]; ok {
			name := optName
			return fmt.Errorf("The %s option cannot be set via command line for this command. For more information, visit https://www.skeema.io/docs/config/#limitations-on-host-and-schema-options", name)
		}
	}
	return nil
}

func (app *App) printHelp(opts map[string]string) {
	fmt.Print(`
Usage:  skeema [<options>] <command>

Skeema is a declarative schema management system for MySQL and MariaDB. It
allows you to export a database schema to the filesystem, and apply online
schema changes by modifying CREATE statements in .sql files.

Commands:
`)
	// Print commands in alphabetical order
	for _, name := range app.cmdOrder {
		cmd := app.commands[name]
		fmt.Printf("      %-20s %s\n", cmd.Name, cmd.Summary)
	}

	fmt.Print(`
Global Options:
  -o, --connect-options value  Comma-separated session options to set upon connecting to each database server
      --debug                  Enable debug logging
  -?, --help[=value]           Display usage information for the specified command
  -H, --host-wrapper value     External bin to shell out to for host lookup; see manual for template vars
      --ignore-func value      Ignore functions that match regex
      --ignore-proc value      Ignore stored procedures that match regex
      --ignore-schema value    Ignore schemas that match regex
      --ignore-table value     Ignore tables that match regex
      --[skip-]my-cnf          Parse ~/.my.cnf for configuration (enabled by default; disable with --skip-my-cnf)
  -p, --password[=value]       Password for database user; omit value to prompt from TTY (default "$MYSQL_PWD")
      --ssl-mode value         Specify desired connection security SSL/TLS usage (valid values: "disabled", "preferred", "required")
  -u, --user value             Username to connect to database host (default "root")
      --version                Display program version

Complete documentation for this command suite is available online:
https://www.skeema.io/docs/commands

`)
}

func (cmd *Command) printHelp() {
	fmt.Printf("\nUsage:  skeema %s [<options>] %s\n\n", cmd.Name, cmd.argsUsage())
	// Print description
	desc := strings.TrimSpace(cmd.Description)
	for _, line := range strings.Split(desc, "\n") {
		fmt.Println(line)
	}
	fmt.Println()
	printOptionGroups(cmd)
	fmt.Printf("Complete documentation for this command is available online:\nhttps://www.skeema.io/docs/commands/%s\n\n", cmd.Name)
}

func (cmd *Command) argsUsage() string {
	switch cmd.Name {
	case "init":
		return "[<environment>]"
	case "diff", "push", "pull", "format", "lint":
		return "[<environment>]"
	case "add-environment":
		return "<environment>"
	default:
		return ""
	}
}

func printOptionGroups(cmd *Command) {
	// Print command-specific options grouped
	printOptionsForCmd(cmd)
	printGlobalOptionsForCmd()
}

