// ConnectionError formats a connection error message consistently
func ConnectionError(host string, port int, socketPath string, dir string, err error) string {
	addr := formatHostAddr(host, port, socketPath)
	return fmt.Sprintf("%s for %s: %s", addr, dir, err.Error())
}

func formatHostAddr(host string, port int, socketPath string) string {
	if socketPath != "" && (host == "" || host == "localhost") {
		return fmt.Sprintf("%s:%s", host, socketPath)
	}
	if port == 0 || port == 3306 {
		return fmt.Sprintf("%s:%d", host, port)
	}
	return fmt.Sprintf("%s:%d", host, port)
}

// formatDSNDisplay formats a DSN for display in error messages  
func formatDSNDisplay(dsn *DSN) string {
	if dsn.Network() == "unix" {
		return fmt.Sprintf("%s:%s", dsn.Host, dsn.Socket)
	}
	port := dsn.Port
	if port == 0 {
		port = 3306
	}
	return fmt.Sprintf("%s:%d", dsn.Host, port)
}

// connectToInstance tries to connect and returns display address and error
func connectToInstance(config map[string]string, opts map[string]string) (*MySQLConn, string, error) {
	dsn := DSNFromConfig(config, opts)
	display := formatDSNDisplay(dsn)
	conn, err := Connect(dsn)
	return conn, display, err
}

// Helpers for subdirectory scanning
func isIgnoredDir(name string) bool {
	// Skip hidden directories
	if strings.HasPrefix(name, ".") {
		return true
	}
	return false
}

// isSystemSchema returns true for MySQL system schemas
func isSystemSchema(name string) bool {
	switch strings.ToLower(name) {
	case "information_schema", "performance_schema", "mysql", "sys", "test":
		return true
	}
	return false
}

// formatOperationCount returns pluralized "operation" string
func formatOperationCount(n int) string {
	if n == 1 {
		return "1 operation"
	}
	return fmt.Sprintf("%d operations", n)
}

// exitCodeForOS converts internal exit code to os exit code  
func exitCodeForOS(code int) int {
	return code
}
