package main

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

func cmdInit() *Command {
	return &Command{
		Name:    "init",
		Summary: "Save a DB server's schemas to the filesystem",
		Description: `Creates a filesystem representation of the schemas on a database server. For
each schema on the DB server (or just the single schema specified by --schema),
a subdir with a .skeema config file will be created. Each directory will be
populated with .sql files containing CREATE statements for every table and
routine in the schema.

When operating on all schemas on the server, this command automatically skips
pre-installed / system schemas (information_schema, performance_schema, mysql,
sys, test).

You may optionally pass an environment name as a command-line arg. This will
affect which section of .skeema config files the host-related options are
written to. For example, running ` + "`" + `skeema init staging` + "`" + ` will add config
directives to the [staging] section of config files. If no environment name is
supplied, the default is "production", so directives will be written to the
[production] section of the file.`,
		MinArgs: 0,
		MaxArgs: 1,
		Options: initOptions,
		Run:     runInit,
	}
}

var initOptions = []*Option{
	{LongName: "dir", ShortName: 'd', Description: `Subdir name to use for this host's schemas (default "<hostname>")`, HasValue: true},
	{LongName: "host", ShortName: 'h', Description: "Database hostname or IP address", HasValue: true},
	{LongName: "include-auto-inc", Description: "Include starting auto-inc values in table files"},
	{LongName: "port", ShortName: 'P', Description: `Port to use for database host (default "3306")`, HasValue: true},
	{LongName: "schema", Description: "Only import the one specified schema; skip creation of subdirs for each schema", HasValue: true},
	{LongName: "socket", ShortName: 'S', Description: `Absolute path to Unix socket file used if host is localhost (default "/tmp/mysql.sock")`, HasValue: true},
	{LongName: "strip-partitioning", Description: "Omit PARTITION BY clause when writing partitioned tables to filesystem"},
}

func runInit(args []string, opts map[string]string) int {
	environment := "production"
	if len(args) > 0 {
		environment = args[0]
	}

	// Host is required
	host, hasHost := opts["host"]
	if !hasHost || host == "" {
		logError("`skeema init` requires --host to be supplied on command-line")
		return ExitFatalUsage
	}

	// Port
	port := 3306
	if portStr, ok := opts["port"]; ok {
		fmt.Sscanf(portStr, "%d", &port)
	}

	// Socket
	socket := ""
	if s, ok := opts["socket"]; ok {
