// importSchema imports all tables and routines from a schema into a directory
func importSchema(conn *MySQLConn, dbName, dir string, opts map[string]string) error {
	// Get tables
	tables, err := getTableSQL(conn, dbName)
	if err != nil {
		return err
	}

	// Get routines
	routines, err := getRoutineSQL(conn, dbName)
	if err != nil {
		return err
	}

	// Write each table to its own file
	for _, t := range tables {
		fname := filepath.Join(dir, sanitizeFilename(t.Name)+".sql")
		content := t.CreateStatement + ";\n"
		if err := os.WriteFile(fname, []byte(content), 0644); err != nil {
			return fmt.Errorf("unable to write %s: %s", fname, err.Error())
		}
	}

	// Write each routine to its own file
	for _, r := range routines {
		fname := filepath.Join(dir, sanitizeFilename(r.Name)+".sql")
		content := r.CreateStatement + ";\n"
		if err := os.WriteFile(fname, []byte(content), 0644); err != nil {
			return fmt.Errorf("unable to write %s: %s", fname, err.Error())
		}
	}

	return nil
}

type TableInfo struct {
	Name            string
	CreateStatement string
}

type RoutineInfo struct {
	Name            string
	Type            string // "PROCEDURE" or "FUNCTION"
	CreateStatement string
}

func getTableSQL(conn *MySQLConn, dbName string) ([]TableInfo, error) {
	result, err := conn.Query(fmt.Sprintf("SHOW FULL TABLES IN `%s` WHERE Table_type = 'BASE TABLE'", dbName))
	if err != nil {
		// Fallback
		result, err = conn.Query(fmt.Sprintf("SHOW TABLES FROM `%s`", dbName))
		if err != nil {
			return nil, err
		}
	}

	var tables []TableInfo
	for _, row := range result.Rows {
		if len(row) == 0 {
			continue
		}
		tableName := row[0]
		createResult, err := conn.Query(fmt.Sprintf("SHOW CREATE TABLE `%s`.`%s`", dbName, tableName))
		if err != nil {
			continue
		}
		if len(createResult.Rows) > 0 && len(createResult.Rows[0]) > 1 {
			tables = append(tables, TableInfo{
				Name:            tableName,
				CreateStatement: createResult.Rows[0][1],
			})
		}
	}
	return tables, nil
}

func getRoutineSQL(conn *MySQLConn, dbName string) ([]RoutineInfo, error) {
	var routines []RoutineInfo

	// Get procedures
	procResult, err := conn.Query(fmt.Sprintf("SHOW PROCEDURE STATUS WHERE Db = '%s'", dbName))
	if err == nil {
		for _, row := range procResult.Rows {
			if len(row) < 2 {
				continue
			}
			procName := row[1]
			createResult, err := conn.Query(fmt.Sprintf("SHOW CREATE PROCEDURE `%s`.`%s`", dbName, procName))
			if err != nil {
				continue
			}
			if len(createResult.Rows) > 0 && len(createResult.Rows[0]) > 2 {
				routines = append(routines, RoutineInfo{
					Name:            procName,
					Type:            "PROCEDURE",
					CreateStatement: createResult.Rows[0][2],
				})
			}
		}
	}

	// Get functions
	funcResult, err := conn.Query(fmt.Sprintf("SHOW FUNCTION STATUS WHERE Db = '%s'", dbName))
	if err == nil {
		for _, row := range funcResult.Rows {
			if len(row) < 2 {
				continue
			}
			funcName := row[1]
			createResult, err := conn.Query(fmt.Sprintf("SHOW CREATE FUNCTION `%s`.`%s`", dbName, funcName))
			if err != nil {
				continue
			}
			if len(createResult.Rows) > 0 && len(createResult.Rows[0]) > 2 {
				routines = append(routines, RoutineInfo{
					Name:            funcName,
					Type:            "FUNCTION",
					CreateStatement: createResult.Rows[0][2],
				})
			}
		}
	}

	return routines, nil
}

func sanitizeFilename(name string) string {
	// Replace characters that aren't safe in filenames
	result := strings.Map(func(r rune) rune {
		if r == '/' || r == '\\' || r == ':' || r == '*' || r == '?' || r == '"' || r == '<' || r == '>' || r == '|' {
			return '_'
		}
		return r
	}, name)
	return result
}
