package main

import (
	"fmt"
	"os"
	"path/filepath"
)

func cmdAddEnvironment() *Command {
	return &Command{
		Name:    "add-environment",
		Summary: "Add a new named environment to an existing host directory",
		Description: `Modifies the .skeema file in an existing host directory to add a new named
environment. For example, if ` + "`" + `skeema init` + "`" + ` was previously used to create a dir
for a host with the default "production" environment, ` + "`" + `skeema add-environment` + "`" + `
could be used to define a "staging" or "development" environment pointing at a
different host and port, or perhaps a "local" environment pointing at localhost
and a socket path.

This command currently only handles very simple cases. For many situations,
editing .skeema files directly is a better approach.`,
		MinArgs: 1,
		MaxArgs: 1,
		Options: addEnvOptions,
		Run:     runAddEnvironment,
	}
}

var addEnvOptions = []*Option{
	{LongName: "dir", ShortName: 'd', Description: `Base dir for this host's schemas (default ".")`, HasValue: true},
	{LongName: "host", ShortName: 'h', Description: "Database hostname or IP address", HasValue: true},
	{LongName: "port", ShortName: 'P', Description: `Port to use for database host (default "3306")`, HasValue: true},
	{LongName: "socket", ShortName: 'S', Description: `Absolute path to Unix socket file used if host is localhost (default "/tmp/mysql.sock")`, HasValue: true},
}

func runAddEnvironment(args []string, opts map[string]string) int {
	envName := args[0]

	// Host is required
	host, hasHost := opts["host"]
	if !hasHost || host == "" {
		logError("`skeema add-environment` requires --host to be supplied on command-line")
		return ExitFatalUsage
	}

	// Determine target directory
	cwd, _ := os.Getwd()
	targetDir := cwd
	if d, ok := opts["dir"]; ok && d != "" {
		if filepath.IsAbs(d) {
			targetDir = d
		} else {
			targetDir = filepath.Join(cwd, d)
		}
	}

	// Check .skeema exists
	skeemaPath := filepath.Join(targetDir, ".skeema")
	if _, err := os.Stat(skeemaPath); os.IsNotExist(err) {
		logError("Dir %s does not have an existing .skeema file! Can only use `skeema add-environment` on a dir previously created by `skeema init`", targetDir)
		return ExitFatalUsage
	}

