cat > /workspace/src/skeema/dirwalk.go << 'GOEOF'
package main

import (
	"os"
	"path/filepath"
	"sort"
	"strings"
)

// DirTarget represents a directory that is a target for skeema operations
type DirTarget struct {
	Dir    string
	Config map[string]string // effective config for this dir+environment
}

// WalkMode controls how directories are traversed
type WalkMode int

const (
	// WalkModeSchemas: only dirs with schema defined (for diff/push)
	WalkModeSchemas WalkMode = iota
	// WalkModeAll: all dirs with .skeema or SQL files (for lint/format/pull)
	WalkModeAll
	// WalkModePull: like schemas but for pull
	WalkModePull
)

// FindDirTargets finds all directories to process, starting from rootDir
// It returns DirTargets in the order they should be processed
func FindDirTargets(rootDir string, environment string, mode WalkMode) ([]DirTarget, error) {
	var targets []DirTarget

	// Get parent config (inherited from dirs above rootDir)
	parentConfig, err := GetParentConfig(rootDir, environment)
	if err != nil {
		return nil, err
	}

	err = walkDirTargets(rootDir, environment, parentConfig, mode, &targets)
	return targets, err
}

// GetParentConfig gets the effective config from all directories ABOVE the given dir
func GetParentConfig(dir string, environment string) (map[string]string, error) {
	config := make(map[string]string)

	// Walk UP from parent of dir to root
	var ancestors []string
	path := filepath.Dir(filepath.Clean(dir))
	for {
		ancestors = append([]string{path}, ancestors...)
		parent := filepath.Dir(path)
		if parent == path {
			break
		}
		path = parent
	}

	for _, d := range ancestors {
		skeemaPath := filepath.Join(d, ".skeema")
		if _, err := os.Stat(skeemaPath); os.IsNotExist(err) {
			continue
		}
		sf, err := ParseSkeemaFile(skeemaPath)
		if err != nil {
			continue
		}
		for k, v := range sf.Sections[""] {
			config[k] = v
		}
		if envSec, ok := sf.Sections[environment]; ok {
			for k, v := range envSec {
				config[k] = v
			}
		}
	}
	return config, nil
}

func walkDirTargets(dir string, environment string, inheritedConfig map[string]string, mode WalkMode, targets *[]DirTarget) error {
	// Read this dir's .skeema file (if any) to get local config
	localConfig := make(map[string]string)
	if HasSkeemaFile(dir) {
		sf, err := ParseSkeemaFile(filepath.Join(dir, ".skeema"))
		if err != nil {
			return err
		}
		for k, v := range sf.Sections[""] {
			localConfig[k] = v
		}
		if envSec, ok := sf.Sections[environment]; ok {
			for k, v := range envSec {
				localConfig[k] = v
			}
		}
	}

	// Merge: parent config + local config
	effectiveConfig := MergeConfig(inheritedConfig, localConfig)

	// Determine if this dir is a target
	isTarget := false
	switch mode {
	case WalkModeSchemas:
		// Target if schema is defined in effective config
		isTarget = HasSchemaConfig(effectiveConfig) && HasHostConfig(effectiveConfig)
	case WalkModePull:
		isTarget = HasSchemaConfig(effectiveConfig) && HasHostConfig(effectiveConfig)
	case WalkModeAll:
		// Target if has SQL files OR has schema defined
		hasSQLFiles := dirHasSQLFiles(dir)
		hasSchema := HasSchemaConfig(effectiveConfig)
		hasHost := HasHostConfig(effectiveConfig)
		hasLocalSkeema := HasSkeemaFile(dir)
		isTarget = (hasSQLFiles || hasSchema || hasLocalSkeema) && (hasHost || hasWorkspaceConfig(effectiveConfig))
	}

	if isTarget {
		*targets = append(*targets, DirTarget{Dir: dir, Config: effectiveConfig})
		// For schema-mode, don't recurse (schema dirs are leaves)
		if mode == WalkModeSchemas || mode == WalkModePull {
			return nil
		}
		// For WalkModeAll, stop recursing once we hit a schema-level dir
		if HasSchemaConfig(effectiveConfig) {
			return nil
		}
	}

	// Recurse into subdirectories
	entries, err := os.ReadDir(dir)
	if err != nil {
		return nil
	}

	// Sort alphabetically
	sort.Slice(entries, func(i, j int) bool {
		return entries[i].Name() < entries[j].Name()
	})

	for _, entry := range entries {
		if !entry.IsDir() {
			continue
		}
		name := entry.Name()
		if isIgnoredDir(name) {
			continue
		}
		subdir := filepath.Join(dir, name)
		if err := walkDirTargets(subdir, environment, effectiveConfig, mode, targets); err != nil {
			return err
		}
	}

	return nil
}

func dirHasSQLFiles(dir string) bool {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return false
	}
	for _, e := range entries {
		if !e.IsDir() && strings.HasSuffix(strings.ToLower(e.Name()), ".sql") {
			return true
		}
	}
	return false
}

func hasWorkspaceConfig(config map[string]string) bool {
	// Has explicit workspace=docker with flavor set
	workspace := config["workspace"]
	return workspace == "docker"
}

// GetSQLFiles returns all .sql files in a directory
func GetSQLFiles(dir string) ([]string, error) {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return nil, err
	}
	var files []string
	for _, e := range entries {
		if !e.IsDir() && strings.HasSuffix(strings.ToLower(e.Name()), ".sql") {
			files = append(files, filepath.Join(dir, e.Name()))
		}
	}
	sort.Strings(files)
	return files, nil
}

// RelativePath returns the path relative to rootDir, or just basename if error
func RelativePath(rootDir, absPath string) string {
	rel, err := filepath.Rel(rootDir, absPath)
	if err != nil {
		return filepath.Base(absPath)
	}
	return rel
}

// FindRootDir finds the root dir containing .skeema files
// by walking up from the current directory
func FindRootDir(startDir string) string {
	dir := filepath.Clean(startDir)
	for {
		if HasSkeemaFile(dir) {
			return dir
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			break
		}
		dir = parent
	}
	return startDir
}
