package main

import (
	"fmt"
	"os"
	"path/filepath"
)

func cmdDiff() *Command {
	return &Command{
		Name:    "diff",
		Summary: "Compare a DB server's schemas to the filesystem",
		Description: `Compares the schemas on database server(s) to the corresponding filesystem
representation of them. The output is a series of DDL commands that, if run on
the DB server, would cause its schemas to now match the definitions from the
filesystem.

You may optionally pass an environment name as a command-line arg. This will
affect which section of .skeema config files is used for processing. For
example, running ` + "`" + `skeema diff staging` + "`" + ` will apply config directives from the
[staging] section of config files, as well as any sectionless directives at the
top of the file. If no environment name is supplied, the default is
"production".

The ` + "`" + `skeema diff` + "`" + ` command is equivalent to running ` + "`" + `skeema push` + "`" + ` with its
--dry-run option enabled.

An exit code of 0 will be returned if no differences were found; 1 if some
differences were found; or 2+ if an error occurred.`,
		MinArgs: 0,
		MaxArgs: 1,
		Options: diffCmdOptions,
		Run:     runDiff,
	}
}

var diffCmdOptions = []*Option{
	{LongName: "alter-wrapper", ShortName: 'x', HasValue: true},
	{LongName: "alter-wrapper-min-size", HasValue: true},
	{LongName: "ddl-wrapper", ShortName: 'X', HasValue: true},
	{LongName: "alter-algorithm", HasValue: true},
	{LongName: "alter-lock", HasValue: true},
	{LongName: "alter-validate-virtual"},
	{LongName: "compare-metadata"},
	{LongName: "exact-match"},
	{LongName: "lax-column-order"},
	{LongName: "lax-comments"},
	{LongName: "partitioning", HasValue: true},
	{LongName: "allow-auto-inc", HasValue: true},
	{LongName: "allow-charset", HasValue: true},
	{LongName: "allow-compression", HasValue: true},
	{LongName: "allow-definer", HasValue: true},
	{LongName: "allow-engine", HasValue: true},
	{LongName: "allow-pk-type", HasValue: true},
	{LongName: "lint", Skippable: true},
	{LongName: "lint-auto-inc", HasValue: true},
	{LongName: "lint-charset", HasValue: true},
	{LongName: "lint-compression", HasValue: true},
	{LongName: "lint-definer", HasValue: true},
	{LongName: "lint-display-width", HasValue: true},
	{LongName: "lint-dupe-index", HasValue: true},
	{LongName: "lint-engine", HasValue: true},
	{LongName: "lint-fk-parent", HasValue: true},
	{LongName: "lint-has-enum", HasValue: true},
	{LongName: "lint-has-fk", HasValue: true},
	{LongName: "lint-has-float", HasValue: true},
	{LongName: "lint-has-routine", HasValue: true},
	{LongName: "lint-has-time", HasValue: true},
	{LongName: "lint-name-case", HasValue: true},
	{LongName: "lint-pk", HasValue: true},
	{LongName: "lint-pk-type", HasValue: true},
	{LongName: "lint-reserved-word", HasValue: true},
	{LongName: "lint-zero-date", HasValue: true},
	{LongName: "allow-unsafe"},
	{LongName: "safe-below-size", HasValue: true},
	{LongName: "verify", Skippable: true},
	{LongName: "brief", ShortName: 'q'},
	{LongName: "concurrent-servers", ShortName: 'c', HasValue: true},
	{LongName: "first-only", ShortName: '1'},
	{LongName: "docker-cleanup", HasValue: true},
	{LongName: "temp-schema", ShortName: 't', HasValue: true},
	{LongName: "temp-schema-binlog", HasValue: true},
	{LongName: "temp-schema-mode", HasValue: true},
	{LongName: "temp-schema-threads", HasValue: true},
	{LongName: "workspace", ShortName: 'w', HasValue: true},
	// These should not be on command line - handled via checkForbiddenOptions
	// but we include them in the options list so they parse (giving a better error)
}

func runDiff(args []string, opts map[string]string) int {
	return runDiffPush(args, opts, false)
}

func runDiffPush(args []string, opts map[string]string, doPush bool) int {
	environment := "production"
	if len(args) > 0 {
		environment = args[0]
	}

	cwd, _ := os.Getwd()

	// Find all schema dirs
	targets, err := FindDirTargets(cwd, environment, WalkModeSchemas)
	if err != nil {
		logError("Error scanning directories: %s", err.Error())
		return ExitError
	}

	if len(targets) == 0 {
		return ExitSuccess
	}

	errCount := 0
	hasDiffs := false

	for _, target := range targets {
		config := target.Config

		// Get host info
		host := config["host"]
		if host == "" {
			// Check if there's a warning about missing host
			if envHasSkeema(target.Dir, environment) {
				logWarn("Skipping %s: no host defined for environment %q", target.Dir, environment)
				logWarn("This command requires a hostname, which can be specified using the host option in a [%s] section of the .skeema file in this directory, or in a parent directory.", environment)
			}
			continue
		}

		// Build DSN
		dsn := DSNFromConfig(config, opts)
		displayAddr := formatDSNDisplay(dsn)

		// Try to connect
		conn, err := Connect(dsn)
		if err != nil {
			logError("Skipping %s for %s: %s", displayAddr, target.Dir, err.Error())
			errCount++
			continue
		}

		// Perform diff/push operations
		diffs, err := performDiff(conn, target.Dir, config, opts)
		conn.Close()

		if err != nil {
			logError("Error processing %s: %s", target.Dir, err.Error())
			errCount++
			continue
		}

		if len(diffs) > 0 {
			hasDiffs = true
			for _, diff := range diffs {
				if doPush {
					fmt.Println(diff)
				} else {
					fmt.Println(diff)
				}
			}
		}
	}

	if errCount > 0 {
		if errCount == 1 {
			logError("Skipped 1 operation due to problem")
		} else {
			logError("Skipped %d operations due to problems", errCount)
		}
		return ExitError
	}

	if hasDiffs {
		return ExitPartial
	}
	return ExitSuccess
}

func envHasSkeema(dir, environment string) bool {
	skeemaPath := filepath.Join(dir, ".skeema")
	if _, err := os.Stat(skeemaPath); os.IsNotExist(err) {
		return false
	}
	return true
}

// performDiff compares filesystem with database and returns DDL statements
func performDiff(conn *MySQLConn, dir string, config map[string]string, opts map[string]string) ([]string, error) {
	// Get schema name
	schema := config["schema"]
	if schema == "" {
		return nil, fmt.Errorf("no schema configured")
	}

	// Get SQL files from filesystem
	sqlFiles, err := GetSQLFiles(dir)
	if err != nil {
		return nil, err
	}

	// TODO: Full diff implementation
	// For now, just return empty (no diffs)
	_ = sqlFiles
	return nil, nil
}
