package main

import (
	"os"
	"path/filepath"
)

func cmdFormat() *Command {
	return &Command{
		Name:    "format",
		Summary: "Normalize format of filesystem representation of database objects",
		Description: `Reformats the filesystem representation of database objects to match the
canonical format shown in SHOW CREATE.

This command relies on accessing a database server to test the SQL DDL in a
temporary location. See the --workspace option for more information.

You may optionally pass an environment name as a command-line arg. This will
affect which section of .skeema config files is used for workspace selection.
For example, running ` + "`" + `skeema format staging` + "`" + ` will apply config directives from
the [staging] section of config files, as well as any sectionless directives at
the top of the file. If no environment name is supplied, the default is
"production".

An exit code of 0 will be returned if all files were already formatted properly;
1 if some files were not already in the correct format; or 2+ if any errors
occurred.`,
		MinArgs: 0,
		MaxArgs: 1,
		Options: formatCmdOptions,
		Run:     runFormat,
	}
}

var formatCmdOptions = []*Option{
	{LongName: "strip-partitioning"},
	{LongName: "write", Skippable: true},
	{LongName: "docker-cleanup", HasValue: true},
	{LongName: "temp-schema", ShortName: 't', HasValue: true},
	{LongName: "temp-schema-binlog", HasValue: true},
	{LongName: "temp-schema-mode", HasValue: true},
	{LongName: "temp-schema-threads", HasValue: true},
	{LongName: "workspace", ShortName: 'w', HasValue: true},
	// These should not be on command line but we need them for correct error messages
	// {LongName: "flavor", HasValue: true}, // from .skeema file only
}

func runFormat(args []string, opts map[string]string) int {
	environment := "production"
	if len(args) > 0 {
		environment = args[0]
	}

	cwd, _ := os.Getwd()

	// Walk all directories
	exitCode := ExitSuccess
	walkFormatLint(cwd, cwd, environment, opts, false, &exitCode)
	return exitCode
}

// walkFormatLint recursively walks directories for format or lint operations
// isLint: true for lint, false for format
func walkFormatLint(rootDir, dir string, environment string, opts map[string]string, isLint bool, exitCode *int) {
	if isLint {
		logInfo("Linting %s", dir)
	} else {
		logInfo("Reformatting %s", dir)
	}

	// Get effective config for this dir
	config, err := getEffectiveConfigForDir(dir, environment)
	if err != nil {
		if isLint {
			relDir := getRelDirName(rootDir, dir)
			logError("Skipping directory %s due to error: %s", relDir, err.Error())
			incrementExitCode(exitCode, ExitFatalUsage)
		} else {
			logError("Skipping %s: %s", dir, err.Error())
			incrementExitCode(exitCode, ExitFatalUsage)
		}
		return
	}

	// Check if this dir needs processing (has SQL files or schema defined)
	hasSQLFiles := dirHasSQLFiles(dir)
	localConfig, _ := GetSkeemaFileDirConfig(dir, environment)
	hasLocalSchema := localConfig["schema"] != ""

	needsProcess := hasSQLFiles || hasLocalSchema
	isLeaf := hasLocalSchema // stop recursion if schema is defined locally

	if needsProcess {
		err := processFormatLint(rootDir, dir, config, environment, opts, isLint, exitCode)
		if err != nil {
			return
		}
	}

	if isLeaf {
		return // Don't recurse into subdirs when this is a schema (leaf) dir
	}

	// Recurse into subdirectories
	entries, err2 := os.ReadDir(dir)
	if err2 != nil {
		return
	}

	var subdirs []string
	for _, e := range entries {
		if e.IsDir() && !isIgnoredDir(e.Name()) {
			subdirs = append(subdirs, filepath.Join(dir, e.Name()))
		}
	}
	// Sort alphabetically
	sortStrings(subdirs)

	for _, subdir := range subdirs {
		walkFormatLint(rootDir, subdir, environment, opts, isLint, exitCode)
	}
}

func sortStrings(ss []string) {
	for i := 0; i < len(ss); i++ {
		for j := i + 1; j < len(ss); j++ {
			if ss[i] > ss[j] {
				ss[i], ss[j] = ss[j], ss[i]
			}
		}
	}
}

// getEffectiveConfigForDir computes the merged config for a dir and environment
// It walks up through parent dirs to find and merge .skeema files
func getEffectiveConfigForDir(dir string, environment string) (map[string]string, error) {
	config := make(map[string]string)

	// Find all dirs from root to this dir
	var dirs []string
	d := filepath.Clean(dir)
	for {
		dirs = append([]string{d}, dirs...)
		parent := filepath.Dir(d)
		if parent == d {
			break
		}
		d = parent
	}

	for _, d := range dirs {
		skeemaPath := filepath.Join(d, ".skeema")
		if _, err := os.Stat(skeemaPath); os.IsNotExist(err) {
			continue
		}
		sf, err := ParseSkeemaFile(skeemaPath)
		if err != nil {
			return nil, err
		}
		// Apply global section
		for k, v := range sf.Sections[""] {
			config[k] = v
		}
		// Apply environment section
		if envSec, ok := sf.Sections[environment]; ok {
			for k, v := range envSec {
				config[k] = v
			}
		}
	}
	return config, nil
}

// getRelDirName returns the relative path from rootDir's PARENT to dir
func getRelDirName(rootDir, dir string) string {
	parentDir := filepath.Dir(filepath.Clean(rootDir))
	rel, err := filepath.Rel(parentDir, dir)
	if err != nil {
		return filepath.Base(dir)
	}
	return rel
}

func processFormatLint(rootDir, dir string, config map[string]string, environment string, opts map[string]string, isLint bool, exitCode *int) error {
	// Check if we have a workspace
	host := config["host"]
	workspace := config["workspace"]
	flavor := config["flavor"]

	if workspace == "docker" {
		if flavor == "" {
			flavor = opts["flavor"]
		}
		// Check for docker command
		if !dockerCommandExists() {
			errMsg := "unable to find `docker` command-line client among directories in PATH"
			if isLint {
				relDir := getRelDirName(rootDir, dir)
				logError("Skipping directory %s due to error: %s", relDir, errMsg)
				logError("Skeema v1.11+ no longer includes a built-in Docker client. If you are using workspace=docker while also running `skeema` itself in a container, be sure to put a Linux `docker` client CLI binary in the container as well.")
				logError("For more information, see https://github.com/skeema/skeema/issues/186#issuecomment-1648483625")
				incrementExitCode(exitCode, ExitError)
			} else {
				logError("Skipping %s: %s", dir, errMsg)
				logError("Skeema v1.11+ no longer includes a built-in Docker client. If you are using workspace=docker while also running `skeema` itself in a container, be sure to put a Linux `docker` client CLI binary in the container as well.")
				logError("For more information, see https://github.com/skeema/skeema/issues/186#issuecomment-1648483625")
				incrementExitCode(exitCode, ExitError)
			}
			return nil
		}
		// TODO: docker workspace support
		return nil
	}

	// Default: temp-schema mode requires host
	if host == "" {
		errMsg := "This command needs either a host (with workspace=temp-schema) or flavor (with workspace=docker), but one is not configured for environment " + `"` + environment + `"`
		if isLint {
			relDir := getRelDirName(rootDir, dir)
			logError("Skipping directory %s due to error: %s", relDir, errMsg)
			incrementExitCode(exitCode, ExitFatalUsage)
		} else {
			logError("Skipping %s: %s", dir, errMsg)
			incrementExitCode(exitCode, ExitFatalUsage)
		}
		return nil
	}

	// Try to connect
	dsn := DSNFromConfig(config, opts)
	displayAddr := formatDSNDisplay(dsn)

	conn, err := Connect(dsn)
	if err != nil {
		errMsg := "Unable to connect to " + displayAddr + " for " + dir + ": " + err.Error()
		if isLint {
			relDir := getRelDirName(rootDir, dir)
			logError("Skipping directory %s due to error: %s", relDir, errMsg)
			incrementExitCode(exitCode, ExitFatalUsage)
		} else {
			logError("Skipping %s: %s", dir, errMsg)
			incrementExitCode(exitCode, ExitFatalUsage)
		}
		return nil
	}
	defer conn.Close()

	// Actual format/lint operations would go here
	// For now, just succeed
	return nil
}

func incrementExitCode(exitCode *int, newCode int) {
	if newCode > *exitCode {
		*exitCode = newCode
	}
}

func dockerCommandExists() bool {
	paths := filepath.SplitList(os.Getenv("PATH"))
	for _, p := range paths {
		if fileExists(filepath.Join(p, "docker")) {
			return true
		}
	}
	return false
}

func fileExists(path string) bool {
	_, err := os.Stat(path)
	return err == nil
}
