	for k, v := range sf.Sections[""] {
		config[k] = v
	}
	// Apply environment section
	if envSec, ok := sf.Sections[environment]; ok {
		for k, v := range envSec {
			config[k] = v
		}
	}
	return config, nil
}

// GetSQLFiles returns all .sql files in a directory
func GetSQLFiles(dir string) ([]string, error) {
	entries, err := os.ReadDir(dir)
	if err != nil {
