	}
	var files []string
	for _, e := range entries {
		if !e.IsDir() && strings.HasSuffix(strings.ToLower(e.Name()), ".sql") {
			files = append(files, filepath.Join(dir, e.Name()))
		}
	}
	sort.Strings(files)
	return files, nil
}

// dirHasSQLFiles returns true if a directory contains any .sql files
func dirHasSQLFiles(dir string) bool {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return false
	}
	for _, e := range entries {
		if !e.IsDir() && strings.HasSuffix(strings.ToLower(e.Name()), ".sql") {
			return true
		}
	}
	return false
}

// isIgnoredDir returns true for directories that should be skipped
func isIgnoredDir(name string) bool {
	return strings.HasPrefix(name, ".")
}

// isSystemSchema returns true for MySQL system schemas
func isSystemSchema(name string) bool {
	switch strings.ToLower(name) {
	case "information_schema", "performance_schema", "mysql", "sys", "test":
		return true
	}
	return false
}

// getRelDirName returns the path relative to rootDir's PARENT to dir
func getRelDirName(rootDir, dir string) string {
	parentDir := filepath.Dir(filepath.Clean(rootDir))
	rel, err := filepath.Rel(parentDir, dir)
	if err != nil {
		return filepath.Base(dir)
	}
	return rel
}

// HasSkeemaFile returns true if dir has a .skeema file
func HasSkeemaFile(dir string) bool {
	_, err := os.Stat(filepath.Join(dir, ".skeema"))
	return err == nil
}

// HasSchemaConfig returns true if the effective config for this directory
// defines a schema option
func HasSchemaConfig(config map[string]string) bool {
	_, ok := config["schema"]
	return ok
}

// HasHostConfig returns true if the effective config defines a host option
func HasHostConfig(config map[string]string) bool {
	_, ok := config["host"]
	return ok
}

// localSkeemaHasSchemaInEnv checks if the LOCAL .skeema has schema for a specific env
// OR in the global section
func localSkeemaHasSchemaInEnv(dir string, environment string) bool {
	skeemaPath := filepath.Join(dir, ".skeema")
	if _, err := os.Stat(skeemaPath); os.IsNotExist(err) {
		return false
	}
	sf, err := ParseSkeemaFile(skeemaPath)
	if err != nil {
		return false
	}
	// Check global section
	if _, ok := sf.Sections[""]["schema"]; ok {
		return true
	}
	// Check the specific environment section
	if envSec, ok := sf.Sections[environment]; ok {
		if _, ok := envSec["schema"]; ok {
			return true
		}
	}
	return false
}
