// localSkeemaHasSchema checks if the LOCAL .skeema file in a dir has a schema key
// in any section (including global section)
func localSkeemaHasSchema(dir string) bool {
	skeemaPath := filepath.Join(dir, ".skeema")
	if _, err := os.Stat(skeemaPath); os.IsNotExist(err) {
		return false
	}
	sf, err := ParseSkeemaFile(skeemaPath)
	if err != nil {
		return false
	}
	// Check global section
	if _, ok := sf.Sections[""]["schema"]; ok {
		return true
	}
	// Check all named sections
	for name, sec := range sf.Sections {
		if name == "" {
			continue
		}
		if _, ok := sec["schema"]; ok {
			return true
		}
	}
	return false
}

// FindDirTargetsForDiff finds directories that are targets for diff/push operations.
// It visits dirs where LOCAL .skeema has schema in any section.
// For each such dir, it checks the effective config for the given environment.
func FindDirTargetsForDiff(rootDir string, environment string) []DirEntry {
	var results []DirEntry
	walkDiffTargets(rootDir, environment, make(map[string]string), &results)
	return results
}

// DirEntry represents a processed directory entry
type DirEntry struct {
	Dir    string
	Config map[string]string // effective merged config for the environment
}

func walkDiffTargets(dir string, environment string, inheritedConfig map[string]string, results *[]DirEntry) {
	// Merge inherited config with local dir's config
	localConfig, _ := getLocalDirConfig(dir, environment)
	effectiveConfig := MergeConfig(inheritedConfig, localConfig)

	// Check if local .skeema has schema in any section
	if localSkeemaHasSchema(dir) {
		*results = append(*results, DirEntry{Dir: dir, Config: effectiveConfig})
		// Continue recursing - diff visits ALL dirs with local schema
	}

	// Recurse into subdirectories
	entries, err := os.ReadDir(dir)
	if err != nil {
		return
	}

	var subdirs []string
	for _, e := range entries {
		if e.IsDir() && !isIgnoredDir(e.Name()) {
			subdirs = append(subdirs, filepath.Join(dir, e.Name()))
		}
	}
	sort.Strings(subdirs)

	for _, subdir := range subdirs {
		walkDiffTargets(subdir, environment, effectiveConfig, results)
	}
}

// FindDirTargetsForPull finds directories that are targets for pull operations.
// Similar to diff but pull uses effective config (inherited) schema.
func FindDirTargetsForPull(rootDir string, environment string) []DirEntry {
	var results []DirEntry
	walkPullTargets(rootDir, environment, make(map[string]string), &results)
	return results
}

func walkPullTargets(dir string, environment string, inheritedConfig map[string]string, results *[]DirEntry) {
	localConfig, _ := getLocalDirConfig(dir, environment)
	effectiveConfig := MergeConfig(inheritedConfig, localConfig)

	hasSchema := effectiveConfig["schema"] != ""
	hasHost := effectiveConfig["host"] != ""

	if hasSchema && hasHost && HasSkeemaFile(dir) {
		*results = append(*results, DirEntry{Dir: dir, Config: effectiveConfig})
		return // leaf - don't recurse
	}

	// Recurse into subdirectories
	entries, err := os.ReadDir(dir)
	if err != nil {
		return
	}

	var subdirs []string
	for _, e := range entries {
		if e.IsDir() && !isIgnoredDir(e.Name()) {
			subdirs = append(subdirs, filepath.Join(dir, e.Name()))
		}
	}
	sort.Strings(subdirs)

	for _, subdir := range subdirs {
