	config := make(map[string]string)
	skeemaPath := filepath.Join(dir, ".skeema")
	if _, err := os.Stat(skeemaPath); os.IsNotExist(err) {
		return config, nil
	}
	sf, err := ParseSkeemaFile(skeemaPath)
	if err != nil {
		return nil, err
	}
	// Apply global section
	for k, v := range sf.Sections[""] {
		config[k] = v
	}
	// Apply environment section
	if envSec, ok := sf.Sections[environment]; ok {
		for k, v := range envSec {
