			} else {
				// No schema anywhere - skip silently
			}
			continue
		}

		if host == "" {
			logWarn("Skipping %s: no host defined for environment %q", dir, environment)
			logWarn("This command requires a hostname, which can be specified using the host option in a [%s] section of the .skeema file in this directory, or in a parent directory.", environment)
			continue
		}

		// Build DSN
		dsn := DSNFromConfig(config, opts)
		displayAddr := formatDSNDisplay(dsn)

		// Try to connect
		conn, err := Connect(dsn)
		if err != nil {
			logError("Skipping %s for %s: %s", displayAddr, dir, err.Error())
			errCount++
			continue
		}

		// Perform diff/push operations
		diffs, err := performDiff(conn, dir, config, opts)
		conn.Close()

		if err != nil {
			logError("Skipping %s for %s: %s", displayAddr, dir, err.Error())
			errCount++
			continue
		}

		if len(diffs) > 0 {
			hasDiffs = true
			for _, diff := range diffs {
				fmt.Println(diff)
			}
		}
	}

	if errCount > 0 {
		if errCount == 1 {
			logError("Skipped 1 operation due to problem")
		} else {
			logError("Skipped %d operations due to problems", errCount)
		}
		return ExitError
	}

	if hasDiffs {
		return ExitPartial
	}
	return ExitSuccess
}

// performDiff compares filesystem with database and returns DDL statements
func performDiff(conn *MySQLConn, dir string, config map[string]string, opts map[string]string) ([]string, error) {
	_ = conn
	_ = dir
	_ = config
	_ = opts
	// TODO: Full diff implementation
	return nil, nil
}

// envHasSkeema returns true if dir has a .skeema file
func envHasSkeema(dir, environment string) bool {
	return HasSkeemaFile(dir)
}

// localSkeemaHasSchemaForEnv checks if the LOCAL .skeema file has schema
// defined in the specific environment section OR global section
// (not inherited from parent)
func localSkeemaHasSchemaForEnv(dir string, environment string) bool {
	return localSkeemaHasSchemaInEnv(dir, environment)
}

// hasLocalSchemaInAnyEnv returns true if LOCAL .skeema has schema in any section
func hasLocalSchemaInAnyEnv(dir string) bool {
	return localSkeemaHasSchema(dir)
}

// getEffectiveSchemaForDir computes the effective schema for a dir+environment
// considering only the config for that specific environment (not cross-env inheritance)
func getEffectiveSchemaForDir(dir string, environment string) string {
	// Walk up from root to dir, collecting schema from global and env sections
	var dirs []string
	d := filepath.Clean(dir)
	for {
		dirs = append([]string{d}, dirs...)
		parent := filepath.Dir(d)
		if parent == d {
			break
		}
		d = parent
	}

	schema := ""
	for _, d := range dirs {
		skeemaPath := filepath.Join(d, ".skeema")
		if _, err := os.Stat(skeemaPath); os.IsNotExist(err) {
			continue
		}
		sf, err := ParseSkeemaFile(skeemaPath)
		if err != nil {
			continue
		}
		if v, ok := sf.Sections[""]["schema"]; ok {
			schema = v
		}
		if envSec, ok := sf.Sections[environment]; ok {
			if v, ok := envSec["schema"]; ok {
				schema = v
			}
		}
	}
	return schema
}
