// getLocalSchemaForEnv returns the schema from the LOCAL .skeema file for a specific
// environment (checks global section then env section). Does NOT inherit from parents.
func getLocalSchemaForEnv(dir string, environment string) string {
	skeemaPath := filepath.Join(dir, ".skeema")
	if _, err := os.Stat(skeemaPath); os.IsNotExist(err) {
		return ""
	}
	sf, err := ParseSkeemaFile(skeemaPath)
	if err != nil {
		return ""
	}
	// Check global section
	schema := sf.Sections[""]["schema"]
	// Check environment section (overrides global)
	if envSec, ok := sf.Sections[environment]; ok {
		if s, ok := envSec["schema"]; ok {
			schema = s
		}
	}
	return schema
}
