# The first parse with nil options fails because --host is unknown!
# The ParseArgs with nil options only knows about globalOptions
# When it encounters --host, it returns an error
# Then the App.Run returns ExitFatalUsage before even finding the command

# The fix: the first parse should be "lenient" - it should find the command name
# without requiring all options to be valid

# The correct approach is to find the command name FIRST, then parse all options
# with both global + command-specific options

# Let me redesign the App.Run to:
# 1. First scan positional args to find command name (without validating options)
# 2. Then parse all args with global + command-specific options

python3 << 'EOF'
with open('/workspace/src/skeema/app.go', 'r') as f:
    content = f.read()

# Replace the Run function
old_run_start = '''func (app *App) Run(args []string) int {
	// First pass: look for --version flag or -? or --help before command name
	// and look for --debug

	// Parse global options first  
	opts, positional, err := ParseArgs(args, nil)
	if err != nil {
		logError("%s", err.Error())
		return ExitFatalUsage
	}

	// Handle --debug
	if _, ok := opts["debug"]; ok {
		debugMode = true
	}

	// Warn about deprecated --my-cnf / --skip-my-cnf
	if _, ok := opts["my-cnf"]; ok {
		logWarn("Option --my-cnf is deprecated. This option will be removed in Skeema v2, and .my.cnf will always be parsed, with additional safety logic already in place. For more information, visit https://www.skeema.io/v2-changes")
	}

	// Handle --version flag  
	if _, ok := opts["version"]; ok {
		fmt.Println(versionString())
		if debugMode {
			logDebug("Exit code 0 (SUCCESS)")
		}
		return ExitSuccess
	}

	// Handle --help[=cmd] flag
	if helpVal, ok := opts["help"]; ok {
		if helpVal != "" {
			// Show help for specific command
			cmd, exists := app.commands[helpVal]
			if !exists {
				logError("Unknown command %q", helpVal)
				return ExitFatalUsage
			}
			if cmd.Name == "version" {
				fmt.Println(versionString())
				return ExitSuccess
			}
			if cmd.Name == "help" {
				app.printHelp(opts)
				return ExitSuccess
			}
			cmd.printHelp()
			return ExitSuccess
		}
		app.printHelp(opts)
		return ExitSuccess
	}

	// Look for command name in positional args
	if len(positional) == 0 {
		app.printHelp(opts)
		if debugMode {
			logDebug("Exit code 0 (SUCCESS)")
		}
		return ExitSuccess
	}

	cmdName := positional[0]
	cmdArgs := positional[1:]

	cmd, exists := app.commands[cmdName]
	if !exists {
		logError("Unknown command %q", cmdName)
		return ExitFatalUsage
	}

	// Parse command-specific options
	// Re-parse all args with command options included
	allOpts, allPositional, err := ParseArgs(args, cmd.Options)
	if err != nil {
		logError("%s", err.Error())
		return ExitFatalUsage
	}'''

new_run_start = '''func (app *App) Run(args []string) int {
	// First, find the command name by scanning positional args
	// (before full option parsing)
	cmdName := findCommandName(args)

	var cmd *Command
	var cmdOpts []*Option
	if cmdName != "" {
		if c, exists := app.commands[cmdName]; exists {
			cmd = c
			cmdOpts = c.Options
		}
	}

	// Parse all args with global + command-specific options
	allOpts, allPositional, err := ParseArgs(args, cmdOpts)
	if err != nil {
		logError("%s", err.Error())
		return ExitFatalUsage
	}'''

