// findCommandName scans args to find the first non-option positional argument
// that matches a command name, to use for option parsing
func findCommandName(args []string) string {
	for i := 0; i < len(args); i++ {
		arg := args[i]
		if arg == "--" {
			// Next args are positional
			if i+1 < len(args) {
				return args[i+1]
			}
			return ""
		}
		if len(arg) > 0 && arg[0] == '-' {
			// This is an option - may or may not have a value
			// We can't easily determine this without knowing the option set
			// So we'll just skip over known value-taking options heuristically
			// For simplicity: if option has '=' it's complete, otherwise check for value pattern
			if strings.Contains(arg, "=") {
				continue
			}
			// Check if this looks like it might take a value (next arg doesn't start with -)
			// We need to be more careful here - skip to avoid complex logic
			// Just check if next arg is a value by seeing if it starts with -
			if i+1 < len(args) && !strings.HasPrefix(args[i+1], "-") {
				// This might be option+value, but we'll just continue
				// The command name should not look like an option value
			}
			continue
		}
		return arg
	}
	return ""
}
GOEOF

